  ('engchanges', 'eng', 'changes', 'Changes column', 'A column for recording the changes from a previous version.', 'Use this column as a short-hand change log for dictionary development.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engcharLength', 'eng', 'charLength', 'character length', 'The number of characters used for the wide names.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engche', 'eng', 'che', 'Chemical', 'A chemical compound.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engchemVir', 'eng', 'chemVir', 'Chemagic viral dna/rna 300 kit', 'Nucleic acid extraction performed using the chemagic viral dna/rna 300 kit.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('engchikungunyaGrp', 'eng', 'chikungunyaGrp', 'Chikungunya Group', 'A group of measures/methods related to chikungunya virus.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engchikv', 'eng', 'chikv', 'Chikungunya virus (CHIKV)', 'Chikungunya virus (CHIKV)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engchild', 'eng', 'child', 'Child relationship', 'Indicated that this is a sample generated from (an)other sample(s) either because of pooling or sub-sampling.', 'NA', '1.0.0', '2.0.0', 'changed to a relationshipID value.', NULL),
  ('engchlamydia', 'eng', 'chlamydia', 'Chlamydia', 'Chlamydia', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engchlamydiaGrp', 'eng', 'chlamydiaGrp', 'Chlamydia Group', 'A group of measures/methods related to chlamydia bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL);
INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('engcity', 'eng', 'city', 'City', 'The city where a site or organization is located; part of the address.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engcJejuni', 'eng', 'cJejuni', 'Campylobacter jejuni bacteria', 'Campylobacter jejuni gene target/measurement', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engcK', 'eng', 'cK', 'Composite Key', 'Composite key for a table.', 'All report tables have a primary key - the composite key acts as a primary key, but it prouced as a combination of other fields. Each row in a report table has unique identifier recorded in the primary key/composite key. ', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engclari', 'eng', 'clari', 'Clarified sample', 'Clarified sample.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engclass', 'eng', 'class', 'Class', 'A unique identifier for a class, which is akin to a sub-group; it''s a way of grouping parts within a given group. A group can have one or more classes to describe different parts of the class. ', 'Currently, class is only used for biologics. For example, SARS-CoV-2 is a group of measures with the following classes of allele, variant, mutation, sequence, and protein.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engclasses', 'eng', 'classes', 'Classes', 'A class is a collection of one or more related measures or methods within a group. A group can have one more more classes to describe different parts or the class. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engclostridiumGrp', 'eng', 'clostridiumGrp', 'Clostridium Group', 'A group of measures/methods related to clostridium bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engcloudy', 'eng', 'cloudy', 'Cloudy', 'Qualitative category for the weather measure, specifying an overcast day with no rain.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; github issue #124 and #204', NULL),
  ('engcm', 'eng', 'cm', 'Centimetres', 'Unit part for the SI unit of centimetres.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engco', 'eng', 'co', 'Contact table Shorthand', 'The abbreviated short name used to reference the The table that contains information about a contact; a person who is the contact of a site or laboratory.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engco2', 'eng', 'co2', 'Carbon Dioxide ', 'A measure of an amount or concentraion of carbon dioxide.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; github issue #202', NULL),
  ('engcod', 'eng', 'cod', 'Chemical Oxygen Demand', 'Chemical oxygen demand.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engcol2Frdg', 'eng', 'col2Frdg', 'Time from collection to storage', 'The amount of time between sample collection and the samples placement in stable storage/refrigeration.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engcolAMRGrp', 'eng', 'colAMRGrp', 'Colistin Anti-microbial resistance group', 'The group for measures and methods pertaining to colistin-related anti-microbial resistance.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engcolGrp', 'eng', 'colGrp', 'Collection group', 'A group of measurement-like attributes related to sample collection.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engcolis', 'eng', 'colis', 'Colistin resistance', 'Colistin-resistant bacteria.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engcollDT', 'eng', 'collDT', 'Collection date time', 'For grab samples this is the date, time and timezone the sample was taken.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('engcollDTEnd', 'eng', 'collDTEnd', 'Collection date time end', 'For integrated time average samples this is the date, time and timezone the sample was finished being taken.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('engcollDTStart', 'eng', 'collDTStart', 'Collection date time start', 'For integrated time averaged samples this is the date, time and timezone the sample was started being taken.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('engcollectSet', 'eng', 'collectSet', 'Sample collection set', 'Methods for collection samples. ', 'Sample collection methods include water, air, and surface. See the attribute `Compartment set` of the sample collection method.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engcollNum', 'eng', 'collNum', 'Collection number', 'The number of subsamples that were combined to create the sample. Use NA for continuous, proportional or passive sampling.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engcollNumPer', 'eng', 'collNumPer', 'Collection period and number ', 'Composite collection number.period.', 'This a composite measure that combines `collection period` (collPer) and `collection number` (collNum). Collection number and period can be used to reduce the number of table headings during data collection. In data storage, `collNum` and `collPeriod` should be transformed to `collPer` and `collNum`. For Grab sample, Surface swab, or Area proportional sample just enter 1
INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('engextractSet', 'eng', 'extractSet', 'Nucleic Acid Extraction set', 'set used for storing all the valid category values for the nucleic acid extraction method.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engexvol', 'eng', 'exvol', 'Extraction volume of sample', 'Extraction volume of sample.', 'Size of the sample that is analyzed.', '1.0.0', '2.0.0', 'description wording and unit set', NULL),
  ('engf456l', 'eng', 'f456l', 'F456L Mutation', 'The FLiRT/SLip variant mutation F456L.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfaeces', 'eng', 'faeces', 'Fecal matter', 'Fecal matter.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engfColiphage', 'eng', 'fColiphage', 'Male-specific (F+) coliphage - general', 'Male-specific (F+) coliphage - general', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfDNA', 'eng', 'fDNA', 'F+ DNA coliphage', 'F+ DNA coliphage', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfield', 'eng', 'field', 'Field sample', 'Specifies a sample taken from the field; directly collected from an area for testing.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; GitHub issue #94', NULL),
  ('engfieldReplicate', 'eng', 'fieldReplicate', 'Field sample replicate', 'A sample divided into two or more homogeneous parts.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; GitHub issue #94', NULL),
  ('engfileLocation', 'eng', 'fileLocation', 'File location of polygon', 'The location of the file containing the geometry of the polygon.', 'File path specified, or a URL', '1.0.0', '2.0.0', 'partID chaned to "fileLoaction" specifying where the file is, not the whole file itself.', NULL),
  ('engfilt', 'eng', 'filt', 'Filtration', 'Describes solid separation from a wastewater sample via filtration. Proceeds further concentration or analysis of the liquid filtrate.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfiNa', 'eng', 'fiNa', 'First Nation', 'Used to categorize a sampleshed that is a First Nation, or on reserve lands.', 'Likely for internal use only, Indigenous data can and should not be shared without explicit consent of the nation in quesiton.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfinVol', 'eng', 'finVol', 'Final volume', 'The final volume of a testing solution or sample.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfirstName', 'eng', 'firstName', 'First name of contact', 'Specifies the first name of a given contact.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfirstReleased', 'eng', 'firstReleased', 'First released version', 'The version in which a part was first released', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfK', 'eng', 'fK', 'Foreign key', 'Foreign key for a table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagAI', 'eng', 'flagAI', 'AI - Inhibition present but addressed', 'The original sample was inhibited; however, the inhibition has been addressed through dilution. The reported concentration estimate is the updated result after addressing inhibition.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagB', 'eng', 'flagB', 'B - Trace levels of contamination', 'Analytical result may be subject to “trace” levels of contamination; the target analyte was also detected in negative controls on the same run as the sample.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagFI', 'eng', 'flagFI', 'FI - Inhibition present and unaddressed', 'The original sample was inhibited; however, the inhibition has not been successfully addressed. Therefore, no concentration estimate has been reported.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagJ', 'eng', 'flagJ', 'J - Weak signal extrapolation', 'Analytical result falls below the lowest concentration of the experiment-specific standard curve but above the y-intercept value; the reported value is based on the extrapolation of the standard curve in the non-linear region.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagND', 'eng', 'flagND', 'ND - Non-detect', 'No amplification occurred in the reaction; non-detect.', 'For the value of a non-detected measure, report the actual value even if it is below the limit of detection. The flag here ensures that it''s recorded as a non-detect regardless. In instances where the original data doesn''t record a value, but only has the flag, please populate the value field with either a 0 if dealing with variant percentages, and a 1 for all other purposes to further indicate a null result. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagUJ', 'eng', 'flagUJ', 'UJ - Trace signal extrapolation', 'Observed quantitation cycle is greater than the experiment-specific standard curve intercept value but evidence of clear amplification was present (i.e., “trace” signal observed); the reported value is based on the extrapolation of the standard curve in the non-linear region.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflagUQ', 'eng', 'flagUQ', 'UQ - Unquantifiable', 'Unquantifiable, Ct value exceeds the maximum value of the standard curve. There was a detect, but we cannot quantify it with certainty.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflavivirusGrp', 'eng', 'flavivirusGrp', 'Flavivirus (West Nile, Dengue, Zika) Group', 'A group of measures/methods related to flaviviruses.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engflirtSLipGrp', 'eng', 'flirtSLipGrp', 'FLiRT/SLip Variant Group', 'The group for measures and methods pertaining to the FLiRT and SLip variants of SARS-CoV-2.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engflirtV', 'eng', 'flirtV', 'FLiRT Variants', 'FLiRT is the name given to an entire family of COVID-19 subvariants that are gaining dominance. They''ve evolved from the JN.1 subvariant.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfloat', 'eng', 'float', 'Float data type', 'The data type for float data.', 'Only used for the dictionary entries of parts.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfloMean', 'eng', 'floMean', 'Flow-normalized mean', 'Mean measure normalized to wastewater flow.', 'Mostly used for reporting specific alleles (N1, N2, E, etc.)', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfloor', 'eng', 'floor', 'Floor', 'Floor of a building or room.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfloRate', 'eng', 'floRate', 'Flow rate', 'Wastewater volumetric flow rate at the sample collection location over the 24-hr period during which the sample was collected.', ' If only an instantaneous flow measurement is available, it may be reported in units of million gallons per day. ', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engflow24hDep', 'eng', 'flow24hDep', 'Flow proportional 24hr sample depreciated', 'A flow proportional 24-hour composite sample generally collected by an autosampler.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engflowClass', 'eng', 'flowClass', 'Flow class', 'Measures and methods related to flow.', 'NA', '2.0.0', '3.0.0', 'partID changed from "flow" to "flowClass"', NULL),
  ('engflowPr', 'eng', 'flowPr', 'Flow proportional sample', 'A flow proportional composite sample generally collected by an autosampler.', 'Use collectionPeriod to describe how many hours the sample was taken. The volume of wastewater taken is proportional to the flow rate flowing at each instant of sampling. This is also called constant time, variable volume (CTVV).', '1.0.0', '2.0.0', 'Removed time period. Use collection period (collectPer) = 24 for 24hr sample', NULL),
  ('engflowUnitSet', 'eng', 'flowUnitSet', 'Volume flow rate unit set', 'Unit set for volume flow  measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflowVol', 'eng', 'flowVol', 'Flow volume', 'Volume of influent.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engflu', 'eng', 'flu', 'Influenza virus measure', 'General influenza virus measure', 'This measure should only be used if there is no other influenza virus measure. See groupID = virusMisc. Use a note to describe the specific measure used. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluA', 'eng', 'fluA', 'Influenza A virus', 'Influenza A virus.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engfluA1', 'eng', 'fluA1', 'Influenza virus A1', 'Influenza virus A1 type', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluA1A2c', 'eng', 'fluA1A2c', 'Influenza virus A1 and A2 combined', 'Measure of influenza virus A1 and A2 combined, usually due to single fluorescence channel.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluA2', 'eng', 'fluA2', 'influenza virus A2', 'influenza virus A2 type', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluAGrp', 'eng', 'fluAGrp', 'Influenza A Virus Group', 'A group of measures/methods related to Influenza A viruses.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfluB', 'eng', 'fluB', 'Influenza virus B', 'Influenza virus B type', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluBGrp', 'eng', 'fluBGrp', 'Influenza B Virus Group', 'A group of measures/methods related to Influenza B viruses.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfluGrp', 'eng', 'fluGrp', 'Influenza Virus General Group', 'A group of measures/methods related to general influenza viruses.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfluH5hema', 'eng', 'fluH5hema', 'Influenza A H5 hemagglutinin gene ', 'Measure of the H5 hemagglutinin gene from the Highly Pathogenic Avian Influenza Virus (HPAIV), the H5N1 Influenza A Virus (IAV) subtype.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfluIAVm', 'eng', 'fluIAVm', 'Influenza A M gene', 'A measure of the M gene found in Influenza A viruses (IAV). The virus has segmented RNA genome and 7th segment, M gene, encodes 2 proteins. M1 is a matrix protein and M2 is a membrane protein. The M gene may be involved in determining host tropism.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfluiDpcr', 'eng', 'fluiDpcr', 'Fluidigm digital PCR', 'Describes a PCR analysis done using FluidIGM''s digital PCR technology.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfluN1neur', 'eng', 'fluN1neur', 'Influenza A N1 neuraminidase gene', 'Measure of the N1 neuraminidase gene from the Highly Pathogenic Avian Influenza Virus (HPAIV), the H5N1 Influenza A Virus (IAV) subtype.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfoggy', 'eng', 'foggy', 'Foggy', 'Qualitative category for the weather measure, specifying a foggy or hazy day.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; github issue #124 and #204', NULL),
  ('engfraction', 'eng', 'fraction', 'Fraction analyzed', 'Fraction of the sample that is analyzed.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engfractionInput', 'eng', 'fractionInput', 'Fraction input (wide table)', 'The partID for the fraction being used in a wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfractionName', 'eng', 'fractionName', 'Fraction name (wide table)', 'The fraction analyzed referenced for the wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfractionSet', 'eng', 'fractionSet', 'Sample fraction set', 'set for the fraction of the sample (solid, liquid, etc.).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfreyja', 'eng', 'freyja', 'Freyja Script', 'Freyja Script for sequencing.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfRNABact', 'eng', 'fRNABact', 'F-Specific RNA bacteriophages', 'A measure for amount of F-Specific RNA bacteriophages.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfRNAColi', 'eng', 'fRNAColi', 'F+ RNA coliphage', 'F+ RNA coliphage', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfrnaG2', 'eng', 'frnaG2', 'F-Specific RNA bacteriophages, G2', 'A measure for amount of G2 F-Specific RNA bacteriophages.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfrozen', 'eng', 'frozen', 'Sample frozen', 'Sample was frozen before analysis or processing', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfst', 'eng', 'fst', 'Field sample temperature', 'Temperature that the sample is stored at while it is being sampled. This field is mainly relevant for composite samples which are either kept at ambient temperature or refrigerated while being sampled.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engfTularensis', 'eng', 'fTularensis', 'Francisella tularensis', 'Francisella tularensis', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engfullDictionarySheetSet', 'eng', 'fullDictionarySheetSet', 'Full dictionary sheets set', 'Worksheets in the full Excel dictionary.', 'The full dictionary is `ODM_full-dictionary.xlxs', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfunderCont', 'eng', 'funderCont', 'Funder contact ID', 'A unique identifier for a funder.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engfunderID', 'eng', 'funderID', 'Funding agency ID', 'The funding agency of the dataset.', 'Use Organization ID to populate this field, and the organizations table to describe contact information and other details for the funding agency. ', '2.0.0', '2.0.0', 'added in V2.0; github issue #205', NULL),
  ('engg215c', 'eng', 'g215c', 'g215c delta-variant gene target', 'g215c delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engg339d', 'eng', 'g339d', 'g339d omicron-variant gene target', 'g339d omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engg496s', 'eng', 'g496s', 'g496s omicron-variant gene target', 'g496s omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engg662s', 'eng', 'g662s', 'g662s delta-variant gene target', 'g662s delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggam', 'eng', 'gam', 'Gamma', 'P.1', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggas', 'eng', 'gas', 'Gas class', 'Measures and methods relating to gas and gases.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
