  ('engrsvAMe', 'eng', 'rsvAMe', 'Respiratory syncytial virus A', 'Human Respiratory Syncytial Virus Type A (RSV A).', 'Refer to Group = `rsv` and `rsv` for measure that are apply to either RSV A or RSV B. ', '2.1.0', '2.1.3', 'added in V2.1.0', NULL),
  ('engrsvB', 'eng', 'rsvB', 'Respiratory syncytial virus B', 'Human Respiratory Syncytial Virus Type B (RSV B).', 'Refer to Group = `rsv` and `rsv` for measure that are apply to either RSV A or RSV B. ', '2.1.0', '2.1.3', 'added in V2.1.0', NULL),
  ('engrsvGrp', 'eng', 'rsvGrp', 'Respiratory syncytial virus (RSV) Group', 'Human Respiratory Syncytial virus (RSV).', 'Refer to Group = `rsvA` and `rsvB` for measure that are specific to RSV A or RSV B, respectively. ', '2.0.0', '2.1.2', 'added in V2.0.0', NULL),
