  ('engsar', 'eng', 'sar', 'Sample relationships table Shorthand', 'The abbreviated short name used to reference the Table for recording the relationships between samples.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engsarsCov2', 'eng', 'sarsCov2', 'SARS-CoV-2', 'A group of measures/methods related to the SARS-CoV-2 virus.', 'SARS-CoV-2 measures have the following classes: proteins, alleles, variants, mutations, diseases.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsas', 'eng', 'sas', 'Sample report table Shorthand', 'The abbreviated short name used to reference the The table that contains information about a sample. A sample is defined as a representative volume of wastewater (or other forms of water or liquid), air, or surface area taken from a site.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engsaSpecimenSet', 'eng', 'saSpecimenSet', 'Sample specimen set', 'A specimen set that inculdes only a sample specimen.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsC', 'eng', 'sC', 'Sparse coverage', 'Sequencing shows sparse coverage, ie. numerical breadth of coverage shows as adequate but coverage plots reveal missing genome pieces.', 'If there are multiple issues to flage, use the multiple issues flag and explain the details in the notes section.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsce', 'eng', 'sce', 'Secondary clarifier effluent depreciated', 'Effluent obtained after secondary clarifiers.', 'Deprecated in version 2, please do not use. Duplicate of the sampleMat categories - refer to those.', '1.0.0', '2.0.0', 'depreciated, used to be in site table.', NULL),
  ('engscf', 'eng', 'scf', 'Standard curve frequency', 'A method for specifying the frequecy over which a standard curve (or ''Master Curve'') is used.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL);
