  ('engscriptVersion', 'eng', 'scriptVersion', 'Genetic sequencing script version', 'Used to specify the script or script version used to extract summary information (i.e. coverage and mutation frequency statistics, etc.) from the sequencing output.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engscsDep', 'eng', 'scsDep', 'Secondary clarifier sludge depreciated', 'Sludge produced by secondary clarifiers.', 'Deprecated in version 2, please do not use. Duplicate of the sampleMat categories - refer to those.', '1.0.0', '2.0.0', 'depreciated, site material like this now captured in sample table', NULL),
