  ('engsettsol', 'eng', 'settsol', 'Settled solids', 'Amount of settled solids from a wastewater sample.', 'May be a volume or a weight, see the unitID for a given measure row for details on a given sample.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsetType', 'eng', 'setType', 'Set type', 'The type of set. i.e. quality set, aggregation set, unit set', 'NA', '2.0.0', '2.0.0', 'NA', NULL),
