  ('engsevSet', 'eng', 'sevSet', 'Severity set', 'A set for severity indicators.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsewEq', 'eng', 'sewEq', 'Sewage equivalent', 'Equivalent unconcentrated volume of wastewater or mass of sludge in PCR reaction', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsewerNetworkFileBLOB', 'eng', 'sewerNetworkFileBLOB', 'Sewer network file link depreciated', 'Link to a file that has any detailed information about the sewer network associated with the site (any format).', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engsewTrTi', 'eng', 'sewTrTi', 'Sewage travel time', 'A measure of sewage travel time, often approximate, from sewage source to the sampling site.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
