  ('engshortSets', 'eng', 'shortSets', 'Shorthand or Short Name Set Type', 'Sets used to group together short names for tables or part types in ODM.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engshrtNameSet', 'eng', 'shrtNameSet', 'Short Name Set', 'The abbreviated short name used to reference the The table that contains information about addresses. Addresses can recorded for sites, organizations or contacts (indivduals). ', 'NA', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engsi', 'eng', 'si', 'Sites table Shorthand', 'The abbreviated short name used to reference the The table that contains information about a site; the location where an environmental sample was taken.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engsin', 'eng', 'sin', 'Single', 'A value that is not an aggregate measurement (ie. not a mean, median, max or any other) and can be a replicate value.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engsinLay', 'eng', 'sinLay', 'Single Layout', 'Specifies the single layout for a sequencing method', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsinProbeOne', 'eng', 'sinProbeOne', 'Singleplex, probe-based, one-step RT-qPCR', 'Describes a PCR method that is singleplex, probe-based, and one-step RT-qPCR.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsiSaSpecimenSet', 'eng', 'siSaSpecimenSet', 'Site or sample specimen set', 'A specimen set that inculdes site or sample specimen.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsiSpecimenSet', 'eng', 'siSpecimenSet', 'Site specimen set', 'A specimen set that inculdes only a site specimen.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsit', 'eng', 'sit', 'Site', 'A measure made on a compartment or property at a site.', 'An example is the wastewater flow rate, taken at a wasteawater treatment plant.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsiteDef', 'eng', 'siteDef', 'Site ID default', 'Used as default when a new sample is created by this reporter. See ID in Site table.', 'Deprecated in version 2, please do not use. Just populate standard SiteID.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engsiteFeat', 'eng', 'siteFeat', 'Site features group', 'A group of environmental measures/methods and those pertaining to the features of a site.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsiteID', 'eng', 'siteID', 'Site ID', 'Unique identifier for the location where a sample was taken.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsiteMeasureID', 'eng', 'siteMeasureID', 'Site measure ID', 'Unique identifier for wide table only. Use when all measures are performed on a single sample.', 'Depreciate in version 2. siteMeasures ', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engsites', 'eng', 'sites', 'Sites table', 'The table that contains information about a site; the location where an environmental sample was taken.', 'The site of an eviromental sample. Information in the site table does not regularly change. Consider using the MeasureReport table if the infomation changes often. ', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsitesOrder', 'eng', 'sitesOrder', 'Sites table column order', 'Specifies the order of the columns in a Sites table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsitesRequired', 'eng', 'sitesRequired', 'Sites table required headers', 'Specifies the columns required in a Sites table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsiteType', 'eng', 'siteType', 'Site Type', 'Type of site or institution where sample was taken.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsiteTypeSet', 'eng', 'siteTypeSet', 'Site set', 'set for the type of sampling site.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engskimMilkFloc', 'eng', 'skimMilkFloc', 'Skimmed milk flocculation', 'Skimmed milk flocculation', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engslod', 'eng', 'slod', 'Sample Limit of Detection (LOD)', 'The minimum level of a target within a sample that would be consistently detectable considering all sample processing steps, from sample concentration leading up to and including amplification and quantification steps of RT-qPCR. In this Protocol, the SLOD is the concentration factor-adjusted ALOD, which provides a theoretical estimate of the minimum concentration in the original sample that would yield consistent detection of the target, assuming no method losses.', 'NA', '2.2.0', '3.0.0', 'changed quality indicator set from general to measure.', NULL),
  ('engslope', 'eng', 'slope', 'slope', 'Slope value of the calibration curve.', 'Used for storing calibration curve information, potentially also applicable for other curve types.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsnfl', 'eng', 'snfl', 'Sewer network file link depreciated 2', 'Link to a file that has any detailed information about the sewer network associated with the site (any format).', 'Depreciate in version 2. This attribute has been changed to referenceLink. Use po_referenceLink to specify polygon link to sewer network file.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engsnowy', 'eng', 'snowy', 'Snowy', 'Qualitative category for the weather measure, specifying a snowy day.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('engsol', 'eng', 'sol', 'Solid fraction (general)', 'Solid fraction of a sample.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsolDry', 'eng', 'solDry', 'Solid Fraction (Dry)', 'Solid fraction of a sample - dry material is analyzed, by drying, baking, etc. of sludge or other solids.', 'NA', '2.3.0', '2.3.0', 'added in v2.3.0 for mapping support', NULL),
  ('engsolid', 'eng', 'solid', 'Solids/Pellet retained', 'The solids or pellet is retained after solid separation/centrifugation.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsolidSep', 'eng', 'solidSep', 'Solid seperation', 'Process used to separate solid and liquid phases of the sample. ', 'Solid seperation is used either prior to or in the absence of the concentration method specified in ''methodConc''.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsolidSeparationSet', 'eng', 'solidSeparationSet', 'Solid separation set', 'set for the separation of solids.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsolWet', 'eng', 'solWet', 'Solid fraction (Wet)', 'Solid fraction of a sample - wet material is analyzed, and not dried. Ex. Sludge.', 'NA', '2.3.0', '2.3.0', 'added in v2.3.0 for mapping support', NULL),
  ('engsource', 'eng', 'source', 'Wide name source', 'The database or table sourced for the wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsourceProtocol', 'eng', 'sourceProtocol', 'Source Protocol ID', 'A protocol that served as a basis for another protocol. This may be due to version changes, or a referencing a protocol that was later adapted.', 'Populate with protocolID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsourceStep', 'eng', 'sourceStep', 'Protocol step source ID', 'Specifies the protocol step which serves as a basis for a given protocol step.', 'Populate with a protocol step ID (stepID).', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsovereignty', 'eng', 'sovereignty', 'Sovereign status of a country', 'Sovereign status of a country, indicating which state has the highest jurisdiction over a given territory.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engspecHum', 'eng', 'specHum', 'Specific humidity', 'Measure for specific humidity, the unit is the ratio of the mass of water vapour and the mass of total air.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspecHumidUnitSet', 'eng', 'specHumidUnitSet', 'Specific humidity unit set', 'Unit set for specific humidity.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspecifies', 'eng', 'specifies', 'Specifies', 'Specifies that the object step or protocol occurs specifies details for the subject step or protocol in the overall protocol container.', 'Use only for protocolRelationships table relationshipID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspecimen', 'eng', 'specimen', 'Specimen', 'The substance or thing upon which the observation was made.', 'Specimens include: site, sample, person and population.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspecimenInput', 'eng', 'specimenInput', 'Specimen input (wide table)', 'The partID for the specimen being used in a wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engspecimenName', 'eng', 'specimenName', 'Specimen name (wide table)', 'The specimen referenced for the wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engspecimens', 'eng', 'specimens', 'Specimens', 'Measures or observations are taken from three types of substances: populations (humans or geographic areas), samples, sites.', 'See partID = specimentID', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspecimenSet', 'eng', 'specimenSet', 'Specimen Set Header', 'An idenfication of a set of specimens that can be applied for a measure or method.', 'NA', '2.2.2', '2.2.2', 'added in 2.2.2', NULL),
  ('engspecimenSets', 'eng', 'specimenSets', 'Specimen sets', 'Sets of specimens.', ' Specimen sets are used when a measure or attribute can be recorded for more than one specimen.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engspeed', 'eng', 'speed', 'Speed class', 'Measures and methods relating to speed.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
