  ('engstabPnd', 'eng', 'stabPnd', 'Stabilization pond', 'Specifies a site type which is a pond designed and built for wastewater treatment to reduce the organic content and remove pathogens from wastewater.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engstandardConc', 'eng', 'standardConc', 'Standard concentrations class', 'Measures and methods relating to standard conentrations.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstandardCurve', 'eng', 'standardCurve', 'Standard curve class', 'Measures and methods relating to generating or recording a standard curve.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstaphGrp', 'eng', 'staphGrp', 'Staphylococcus Group', 'A group of measures/methods related to staphylococcus bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstateProvLevel', 'eng', 'stateProvLevel', 'Departments, states, or provinces', 'Departments, states, or provinces', 'NA', '2.0.0', '3.0.0', 'Reactivated as organization level and sector categorical inputs, rather than attributes.', NULL),
  ('engstateProvReg', 'eng', 'stateProvReg', 'State, Province, or Region', 'The state, province, or region where a site or organization is located; part of the address.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engstatus', 'eng', 'status', 'Status', 'Whether the part is still active and can be used in the most current ODM version. Values are ''active'' or ''inactive''.', 'The status of the part or list. ''active'' means the part is used in the dictionary version. ''inactive'' means the part has been retired and not longer used in the version.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstatusSet', 'eng', 'statusSet', 'Status set', 'A set for partID = Status to indicate whether a part is in current use or not.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstdConcentrationUnitSet', 'eng', 'stdConcentrationUnitSet', 'Standard concentration unit set', 'Unit set for concentration measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstdCurveMet', 'eng', 'stdCurveMet', 'Standard Curve Calculation Method', 'Describes the specific approach used for calculating a standard curve.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstdCurveSet', 'eng', 'stdCurveSet', 'Standard Curve Calculation Set', 'The set capturing containing all of the valid methods for the PCR standard curve calculations.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstec', 'eng', 'stec', 'Shiga-toxin-producing Escheria coli (STEC)', 'Shiga-toxin-producing Escheria coli (STEC).', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engsTemp', 'eng', 'sTemp', 'Storage temp', 'Temperature that the sample is stored at in Celsius.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engstepID', 'eng', 'stepID', 'Protocol Step ID', 'The unique identifier for a specific protocol step.', 'Protocol Steps are the component parts of a larger protocols, the latter being linked to specific measure reports.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepIDObj', 'eng', 'stepIDObj', 'Step ID Object', 'The object of the relationship between one protocol step and another step or protocol, within a given protocol ID container.', 'Populate this field using Protocol Step ID (partID = stepID). Together with `protocolIDSub` or `stepIDSub` and `relationshipID` the row of `protocolRelationships` should say: [protocolIDSubject or stepIDSubject]  [relationshipID] [protocolIDObject or stepIDObject]. Ex: stepIDSubject  precedes protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepIDSub', 'eng', 'stepIDSub', 'Step ID Subject', 'The subject of the relationship between one protocol step and another step or protocol, within a given protocol ID container.', 'Populate this field using Protocol ID (partID = stepID). Together with `protocolIDSub` or `stepIDSub` and `relationshipID` the row of `protocolRelationships` should say: [protocolIDSubject or stepIDSubject]  [relationshipID] [protocolIDObject or stepIDObject]. Ex: stepIDSubject  precedes protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepProvenanceID', 'eng', 'stepProvenanceID', 'Method step parent ID', 'A method step that served as a basis for another method step. This may be due to version changes, or a referencing a method set that was later adapted.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepVer', 'eng', 'stepVer', 'Protocol step version', 'Specifies the version of a given protocol step.', 'Version of the method step. Semantic versioning is recommended.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engstEr', 'eng', 'stEr', 'Standard Error', 'The standard error of a series of measurements.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstercobilin', 'eng', 'stercobilin', 'Stercobilin', 'Stercobilin is a tetrapyrrolic bile pigment and is one end-product of heme catabolism. It is the chemical responsible for the brown color of human feces and was originally isolated from feces in 1932.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstorTempDef', 'eng', 'storTempDef', 'Sewer network file blob', 'A file blob that has any detailed information about the sewer network associated with the site (any format).', 'Deprecated in version 2, please do not use. Refer to WKT and EPSG instead.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engstoTim', 'eng', 'stoTim', 'Storage time', 'Length of time that a sample was in storage.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstrepGrp', 'eng', 'strepGrp', 'Streptococcus Group', 'A group of measures/methods related to streptococcus bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstrepPneu', 'eng', 'strepPneu', 'Streptococcus pneumoniae', 'Streptococcus pneumoniae', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsu', 'eng', 'su', 'Summary worksheet Shorthand', 'The abbreviated short name used to reference the Summary sheet of the dictionary.xlxs file.', 'sheet support', '2.2.2', '3.0.0', 'depreciated in version 3', NULL),
  ('engsubVar', 'eng', 'subVar', 'Sub-variant or lineage', 'A unit used to report a specific genetic lineage, or to specify that a reported variant is a sub-variant of another.', 'Combine in a measure report if necessary.', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #120', NULL),
  ('engsuc', 'eng', 'suc', 'Sucralose', 'Sucralose (usually measured as a human fecal chemical indicator)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsum14', 'eng', 'sum14', 'Rolling sum of previous 14 days', 'The rolling sum of case counts/some kind of count over the previous 14 days.', 'Aggregation for a population or disease measure to explain population-level clinical effects.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsumm', 'eng', 'summ', 'Summary', 'Short description of the assay and how it is different from the other assay methods.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsummary', 'eng', 'summary', 'Summary worksheet', 'Summary sheet of the dictionary.xlxs file.', 'The summary sheet contains versioning and changelog.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsunny', 'eng', 'sunny', 'Sunny', 'Qualitative category for the weather measure, specifying a clear and sunny day.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('engsurf', 'eng', 'surf', 'Surface compartment', 'A measure or observation made from a substance on a surface.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurface', 'eng', 'surface', 'Other surface', 'Surface other than floor or desk.', 'See also categories for floor and desk. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
