  ('engswrSet', 'eng', 'swrSet', 'Sewer catchment area', 'Sewer catchment area.', 'NA', '1.0.0', '2.0.0', 'Name Change (from Polygon Type)', NULL),
  ('engsynthetic', 'eng', 'synthetic', 'Synthetic sample', 'A synthetic or artificially generated sample.', 'Synthetic samples are artificially created by mixing known quantities of target substances or organisms with clean water, often in a laboratory setting. These samples are used as controls, benchmarks, or calibration standards during the analysis process to ensure accurate and reliable results. For instance, a synthetic sample containing a known concentration of a specific pollutant might be used to calibrate analytical equipment or to test the efficiency of a new detection method.', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('engt19r', 'eng', 't19r', 't19r delta-variant gene target', 't19r delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt3646a', 'eng', 't3646a', 't3646a delta-variant gene target', 't3646a delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt547k', 'eng', 't547k', 't547k omicron-variant gene target', 't547k omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt9i', 'eng', 't9i', 't9i omicron-variant gene target', 't9i omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtables', 'eng', 'tables', 'Tables', 'Tables are where measures, methods and attributes are recorded. Tables represent the main entities of the environmental surveillance. There', 'An example of a  table is `site` a collection of attributes such as site name and address to describe where environment samples are taken. PHES-ODM has report tables, but users can create their own tables as well.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtableSet', 'eng', 'tableSet', 'Table column set', 'The set for valid inputs in table columns.', 'These categories are used in the parts list for columns named after tables to indicate the position and function of a given part in the entity relationship diagram of the data model.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtableSupport', 'eng', 'tableSupport', 'Table Support', 'Parts designed to support the metadata definition oftables in the parts table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtaqpatN', 'eng', 'taqpatN', 'TaqPath N sars-cov-2 gene target', 'TaqPath N sars-cov-2 mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtaqpatS', 'eng', 'taqpatS', 'TaqPath S sars-cov-2 gene target', 'TaqPath N sars-cov-2 mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtemp', 'eng', 'temp', 'Sample temperature', 'Temperature of the sample measured in degrees Celcius', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
