  ('engtemperatureUnitSet', 'eng', 'temperatureUnitSet', 'Temperature unit set', 'Unit set for temperature measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtemplateSheetSet', 'eng', 'templateSheetSet', 'Template Sheet Set', 'Worksheets in the full generic ODM surveillance template (all tables).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtempSet', 'eng', 'tempSet', 'Template Set', 'The organizing set for templates.', 'NA', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('engtempType', 'eng', 'tempType', 'Nucelic Acid Template Type', 'Specifies whether a PCR or sequencing used RNA or DNA as the template for the reaction.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtempVol', 'eng', 'tempVol', 'Nucleic acid template volume', 'The volume of DNA or RNA template used for PCR. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engterminal', 'eng', 'terminal', 'Airport terminal', 'Airport terminal sample shed category type', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtesDate', 'eng', 'tesDate', 'Test date', 'Date that the covid-19 test was performed.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engtest', 'eng', 'test', 'Number of tests performed', 'Number of tests performed.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('engtesting', 'eng', 'testing', 'Protocol testing', 'A measure or sample taken to test a new method. These measures are typically used for internal lab uses and not reported to external partners.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtetAMRGrp', 'eng', 'tetAMRGrp', 'Tetracycline Anti-microbial resistance Group', 'The group for measures and methods pertaining to tetracycline-related anti-microbial resistance.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engtetW', 'eng', 'tetW', 'TetW Tetracycline-resistance gene target', 'The tetW tetracycline anti-microbial resistance gene target.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engthermMag', 'eng', 'thermMag', 'thermo magmax microbiome ultra nucleic acid isolation kit', 'Nucleic acid extraction performed using the thermo magmax microbiome ultra nucleic acid isolation kit.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engthermMagmax', 'eng', 'thermMagmax', 'thermo magmax viral/pathogen nucleic acid isolation kit', 'thermo magmax viral/pathogen nucleic acid isolation kit', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtimeClass', 'eng', 'timeClass', 'Time class', 'Measures and methods relating to time.', 'NA', '2.0.0', '3.0.0', 'partID changed from "time" to "timeClass"', NULL),
  ('engtimePr', 'eng', 'timePr', 'Time proportional sample', 'A time proportional composite sample generally collected by an autosampler.', 'Use collectionPeriod to describe how many hours the sample was taken.', '1.0.0', '2.0.0', 'Removed time period. Use collection period (collectPer) = 24 for 24hr sample', NULL),
  ('engtimeUnitSet', 'eng', 'timeUnitSet', 'Time unit set', 'The unit set for measures of time.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtkn', 'eng', 'tkn', 'Total Kjeldahl Nitrogen', 'A measure of Total Kjeldahl Nitrogen; ie. the sum of nitrogen bound in organic substances, nitrogen in ammonia (NH3-N) and in ammonium (NH4+-N) in the chemical analysis of soil, water, or waste water.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtld', 'eng', 'tld', 'Country code top-level domain', 'The internet top-level domain generally used or reserved for a country, sovereign state, or dependent territory identified with a country code.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engtn', 'eng', 'tn', 'Total Nitrogen', 'Total nitrogen concentration, as N.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engtotal', 'eng', 'total', 'Total amount or count - the sum', 'The total number or final count of cases, or other defined metric.', 'Aggregation for a population or disease measure to explain population-level clinical effects.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtp24s', 'eng', 'tp24s', 'Time Proportional 24hr sample', 'A time proportional 24-hour composite sample generally collected by an autosampler.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engtPallidum', 'eng', 'tPallidum', 'Treponema pallidum', 'Treponema pallidum', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtr', 'eng', 'tr', 'Translation look-up table Shorthand', 'The abbreviated short name used to reference the Look up table for translations of the description, label, and instruction for all parts.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engtranslationID', 'eng', 'translationID', 'Synthetic ID for the translations table', 'A unique, autoincremental ID generated to produce a unique identifier and primary key for each row of the translations table.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtranslations', 'eng', 'translations', 'Translation look-up table', 'Look up table for translations of the description, label, and instruction for all parts.', 'The default language if a translation is not specified is English.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtranslationsOrder', 'eng', 'translationsOrder', 'Translation table column order', 'Specifies the order of the columns in the Translation table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtranslationsRequired', 'eng', 'translationsRequired', 'Translation table required headers', 'Required headers in the Translations table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtreponemaGrp', 'eng', 'treponemaGrp', 'Treponema Group', 'A group of measures/methods related to treponema bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtrichomonasGrp', 'eng', 'trichomonasGrp', 'Trichomonas Group', 'A group of measures/methods related to trichomonas bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
