  ('engtrizol', 'eng', 'trizol', 'trizol, zymo mag beads w/ zymo clean and concentrator', 'Nucleic acid extraction performed using the trizol, zymo mag beads w/ zymo clean and concentrator method.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtrizolEtOH', 'eng', 'trizolEtOH', 'trizol, garnet bead beating, alcohol precipitation', 'trizol, garnet bead beating, alcohol precipitation', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtrizolRNA', 'eng', 'trizolRNA', 'trizol and RNA purification kit', 'trizol and RNA purification kit', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engts', 'eng', 'ts', 'Total solids concentration', 'Total solids concentration', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
