  ('engtuberculosisGrp', 'eng', 'tuberculosisGrp', 'Tuberculosis Group', 'A group of measures/methods related to tuberculosis.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtularemiaGrp', 'eng', 'tularemiaGrp', 'Francisella tularensis (tularemia) Group', 'A group of measures/methods related to Francisella tularensis.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engturb', 'eng', 'turb', 'Turbidity', 'A measure for the turbidity of water, or a liquid sample, quanitfying the relative clarity or opcaity of a liquid. Highly indicative of water quality.', 'NA', '1.0.0', '2.0.0', 'github issue #122', NULL),
