  ('enguCampus', 'eng', 'uCampus', 'University campus', 'Universityor college campus - comprising an entire campus or part of a campus.', 'See also ''Higher Education Domitory".', '1.1.0', '2.0.0', 'added in version 1.1', NULL),
  ('engugG', 'eng', 'ugG', 'Micrograms per gram', 'Micrograms per gram', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
