  ('enguL', 'eng', 'uL', 'Micro-litres', 'The unit of microlitres.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engundisc', 'eng', 'undisc', 'Undisclosed or Not Provided', 'A value has been recorded, however it was not included in the dataset.', 'Missing value indicator for data that has not been shared or disclosed with outside parties.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunique', 'eng', 'unique', 'Unique sample', 'A unique sample, not duplicated.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('engunit', 'eng', 'unit', 'Unit', 'The units of a measurement.', 'Different units that are used to describe measurement values. Units are combined into UnitSetIDs. Please requests new units by creating an issue in the ODM repository.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunitInput', 'eng', 'unitInput', 'Unit input (wide table)', 'The partID for the unit being used in a wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engunitless', 'eng', 'unitless', 'Unitless measure', 'A unit for unitless measures, like pH.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunitlessUnitSet', 'eng', 'unitlessUnitSet', 'Unitless unit set', 'Unit set for measurements that does not have units.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunitName', 'eng', 'unitName', 'Unit name (wide table)', 'The unit referenced for the wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engunits', 'eng', 'units', 'Units', 'The unit of the measurement.', 'Every measurement must have a unit. Meaning, `units` are a mandatory field whenever a measurement is recorded.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunitSet', 'eng', 'unitSet', 'Unit set', 'An idenfication of a set of units that can be used for a measure or method.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunitSets', 'eng', 'unitSets', 'Unit sets', 'Sets of units. Contains units that are associated with part types such as measures.', 'Sets are lists of input values. Each input value within a set is a part (has a partID) that can be reused between sets. For example, a set A could contain the values of ''yes'' and ''no''; and set B could contain the values of ''yes'', ''no'', and ''maybe.'' partTypes with sets include aggregations, compartments, missingness, quality flags, specimens, and units. Measures with categories and dataTypes have their own specific sets (catSetID) because their input values are unique and are not reused.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engunlicense', 'eng', 'unlicense', 'The Unlicense', 'The licensing for the measure or data set is managed under The Unlicense.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enguntracent', 'eng', 'untracent', 'Ultracentrifugation', 'Ultracentrifugation', 'Should typically be linked to a lower limit, and some indication of data spread (ie. standard deviation), and a mean/median measure.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engupperCI95', 'eng', 'upperCI95', 'Upper limit of a 95% confidence interval', 'Specifies the the upper limit of a 95% confidence interval.', 'A catch-all category for upstream wastewater sampling sites, including major sewer pipelines and pumping stations.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engupstream', 'eng', 'upstream', 'Upstream sites', 'A general site type for upstream wastewater sampling sites.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('engureaplasma', 'eng', 'ureaplasma', 'Ureaplasma', 'Ureaplasma', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engureaplasmaGrp', 'eng', 'ureaplasmaGrp', 'Ureaplasma Group', 'A group of measures/methods related to ureaplasma bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engurobilin', 'eng', 'urobilin', 'Urobilin or urochrome', 'Urobilin or urochrome is the chemical primarily responsible for the yellow color of urine. It is a linear tetrapyrrole compound that, along with the related colorless compound urobilinogen, are degradation products of the cyclic tetrapyrrole heme.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enguSCm', 'eng', 'uSCm', 'Micro-Siemens per centimetre', 'Micro-siemens per centimetre.', 'NA', '1.0.0', '2.0.0', 'maintained', NULL),
  ('enguSiteMeasureID', 'eng', 'uSiteMeasureID', 'U site measure ID', 'Unique identifier for each measurement for a site.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engutc', 'eng', 'utc', 'Coordinated universal time (UTC) zone', 'UTC – Time zone.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engutcDST', 'eng', 'utcDST', 'Coordinated universal time (UTC) zone in daylight savings', 'Time zone during Daylight Saving Time.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engutilities', 'eng', 'utilities', 'Utilities sector or organization', 'Describes organization that manage or provide utilities services, whether water, gas, heat, etc.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
