  ('fralowVol', 'fra', 'lowVol', 'Échantillon de faible volume', 'L''échantillon est de faible volume, mais a été analysé malgré tout. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fralPGC', 'fra', 'lPGC', 'Faible pourcentage du génome capturé', 'Seul un faible pourcentage du génome a été capturé. ', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
