  ('fram3S', 'fra', 'm3S', 'Mètres cubes par seconde', 'Mètres cubes par seconde.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('framalariaGrp', 'fra', 'malariaGrp', 'Groupe Plasmodium ou Malaria', 'Un groupe de mesures/méthodes relatives aux parasites plasmodium ou à la malaria.', 'Utilisé pour décrire les informations sur l''organisme pour les mesures générales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
