  ('frameaslesGrp', 'fra', 'measlesGrp', 'Groupe rougeole', 'Un groupe de mesures/méthodes relatives au virus de la rougeole.', 'Utilisé pour décrire les informations sur l''organisme pour les mesures générales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frameasOth', 'fra', 'measOth', 'Autre mesure', 'Autre mesure, non spécifiée autrement dans les mesures.', 'Ajouter une description à la catégorieAutres.', '1.0.0', '2.0.0', 'Depreciated in version 2 with all "other" fields', NULL),
  ('frameasQualitySet', 'fra', 'measQualitySet', 'Ensemble de qualité des mesures', 'Un ensemble d''indicateurs de qualité pour toute mesure, comprend toutes les options d''indicateurs de qualité pour toute mesure.', 'Utilisé comme "n''importe quel ensemble de qualité" pour les mesures, mais exclut les indicateurs de qualité de l''échantillon pour éviter la confusion et les erreurs de saisie de données.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasure', 'fra', 'measure', 'ID de la mesure', 'Une mesure ou une observation de toute substance, y compris une substance biologique, physique ou chimique.', 'Les mesures sont organisées en groupes et en classes (sous-groupes). ', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasureInput', 'fra', 'measureInput', 'Entrée de la mesure (tableau large)', 'Le partID de la mesure utilisée dans un nom large.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frameasureLic', 'fra', 'measureLic', 'Licence de mesure', 'Spécifie les licences d''accès et d''utilisation pour une mesure unique donnée.', 'Rempli par partID = licenseID', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasurements', 'fra', 'measurements', 'Mesure de la composante', 'Une observation enregistrée à partir d''un spécimen (c''est-à-dire un site, un échantillon, une personne ou une population).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasureName', 'fra', 'measureName', 'Nom de la mesure (tableau large)', 'La mesure référencée pour le nom large.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frameasureRepID', 'fra', 'measureRepID', 'ID du rapport de mesure', 'Identifiant unique pour la mesure pour la table "WWMeasurement"', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasures', 'fra', 'measures', 'Table de rapport de mesure', 'La table qui contient de l''information et des détails sur une mesure donnée.', 'NA', '1.0.0', '2.0.0', 'combined all measures tables into a single table', NULL),
  ('frameasureSetRepID', 'fra', 'measureSetRepID', 'ID du rapport de l''ensemble de mesures', 'Identifiant unique permettant de relier un groupe de mesures reliées entre elles.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasureSets', 'fra', 'measureSets', 'Table de rapport des ensembles de mesures', 'La table qui identifie les ensembles de mesures.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasureSetsOrder', 'fra', 'measureSetsOrder', 'L’ordre des colonnes de la table d''ensemles de mesure', 'Indique l’ordre des colonnes dans une table d''ensembles de mesure.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameasureSetsRequired', 'fra', 'measureSetsRequired', 'Exigences de la table d''ensembles de mesure', 'Indique les colonnes requises dans une table d''ensembles de mesure.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
