  ('framenr', 'fra', 'menr', 'Moyenne arthmétique normalisée', 'Moyenne arithmétique normalisée.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frameOthDe', 'fra', 'meOthDe', 'Déscription d''autre mésure', 'Autre type de site d''échantillonnage. Ajouter une description dans la colonne "typeOther"', 'NA', '1.0.0', '2.0.0', 'Depreciated in version 2 with all "other" fields', NULL),
