  ('frascriptSet', 'fra', 'scriptSet', 'Ensemble de catégories de script de séquençage', 'L''ensemble des catégories pour les versions de script ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frascriptVersion', 'fra', 'scriptVersion', 'Version du script de séquençage génétique', 'Utilisé pour spécifier le script ou la version du script utilisé pour extraire les informations sommaires (c''est-à-dire les statistiques de couverture et de fréquence de mutation, etc.) de la sortie du séquençage.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
