  ('frasites', 'fra', 'sites', 'Table de site', 'La table qui contient de l''information sur un site ; l''endroit où un échantillon environnemental a été prélevé.', 'Le site d''un échantillon eviromental. Les informations contenues dans la table site ne changent pas régulièrement. Envisagez d''utiliser la table MeasureReport si les informations changent souvent. ', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frasitesOrder', 'fra', 'sitesOrder', 'L’ordre des colonnes de la table de sites', 'Indique l’ordre des colonnes dans une table de sites.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasitesRequired', 'fra', 'sitesRequired', 'Exigences de la table de sites', 'Indique les colonnes requises dans une table de sites.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasiteType', 'fra', 'siteType', 'Type de site', 'Type de site ou d''institution du site d''échantillonnage.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frasiteTypeSet', 'fra', 'siteTypeSet', 'Ensemble de catégories de sites', 'Ensemble de catégories pour le type de site d''échantillonnage.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraskimMilkFloc', 'fra', 'skimMilkFloc', 'Floculation du lait écrémé', 'Floculation du lait écrémé', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraslod', 'fra', 'slod', 'Sample Limit of Detection (LOD)', 'Le niveau minimum d''une cible dans un échantillon qui serait détectable de façon constante en tenant compte de toutes les étapes de traitement de l''échantillon, depuis la concentration de l''échantillon jusqu''aux étapes d''amplification et de quantification de la RT-qPCR, y compris ces dernières. Dans ce protocole, la SLOD est la ALOD ajustée au facteur de concentration, qui fournit une estimation théorique de la concentration minimale dans l''échantillon original qui permettrait une détection constante de la cible, en supposant qu''il n''y ait pas de perte de méthode.', 'NA', '2.2.0', '3.0.0', 'changed quality indicator set from general to measure.', NULL),
  ('fraslope', 'fra', 'slope', 'pente', 'Valeur de la pente de la courbe d''étalonnage.', 'Utilisé pour stocker des informations sur la courbe d''étalonnage, potentiellement applicable aussi pour d''autres types de courbes.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL);
INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('frasnfl', 'fra', 'snfl', 'Lien vers le fichier du réseau d''égouts', 'Lien vers un fichier contenant toute information additionnelle au sujet du réseau d''égouts associé é ce site d''échantillonnage (tous les formats sont acceptés).', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('frasnowy', 'fra', 'snowy', 'Neigeux', 'CatSetégorie qualitative pour la mesure météorologique, spécifiant un jour de neige.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('frasol', 'fra', 'sol', 'Fraction solide', 'Fraction solide.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frasolDry', 'fra', 'solDry', 'Fraction solide (sèche)', 'Fraction solide d''un échantillon - le matériau sec est analysé, par séchage, cuisson, etc. des boues ou autres solides.', 'NA', '2.3.0', '2.3.0', 'added in v2.3.0 for mapping support', NULL),
  ('frasolid', 'fra', 'solid', 'Solides/Pellets retenus', 'Les solides ou le culot sont retenus après la séparation/centrifugation des solides.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frasolidSep', 'fra', 'solidSep', 'Séparation des solides', 'Le procès utilisé pour séparer les phases solides et liquides de l''échantillon, soit avant, soit en l''absence de la méthode de concentration spécifiée dans "methodConc".', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasolidSeparationSet', 'fra', 'solidSeparationSet', 'Ensemble de catégories de séparation des solides', 'Ensemble de catégories pour la séparation des solides.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasolWet', 'fra', 'solWet', 'Fraction solide (humide)', 'Fraction solide d''un échantillon - le matériau humide est analysé, et non séché. Ex. Boues.', 'NA', '2.3.0', '2.3.0', 'added in v2.3.0 for mapping support', NULL),
  ('frasource', 'fra', 'source', 'Source du nom large', 'La base de données ou la table à l''origine du nom large.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frasourceProtocol', 'fra', 'sourceProtocol', 'Source du protocole', 'Utilisé pour indiquer le protocole qui a servi de référence ou de base pour le protocole actuel.', 'Remplir avec protocolID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasourceStep', 'fra', 'sourceStep', 'Source de l''étape du protocole', 'Spécifie l''étape de protocole qui sert de base à une étape de protocole.', 'Remplir avec un ID d''étape de protocole (stepID)', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasovereignty', 'fra', 'sovereignty', 'Statut souverain d''un pays', 'Statut de souveraineté d''un pays, indiquant quel État a la plus haute juridiction sur un territoire donné.', 'Préprogrammés dans les tables du dictionnaire, ils ne sont pas modifiables par les utilisateurs.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('fraspecHum', 'fra', 'specHum', 'Humidité specifique', 'Mesure d''humidité spécifique, l''unité est le rapport entre la masse de la vapeur d''eau et la masse de l''air total.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspecHumidUnitSet', 'fra', 'specHumidUnitSet', 'Ensemble d''unités d''humidité spécifique', 'Ensemble d''unités pour les mesures d''humidité spécifique.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspecifies', 'fra', 'specifies', 'Spécifie', 'Indique que l''objet étape ou protocole spécifie les détails du sujet étape ou protocole dans le conteneur de protocole global.', 'À n''utiliser que pour la relation ID de la table protocolRelationships table relationshipID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspecimen', 'fra', 'specimen', 'ID du spécimen', 'La substance ou la chose sur laquelle l''observation a été faite.', 'Les spécimens comprennent : site, échantillon, personne et population.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspecimenInput', 'fra', 'specimenInput', 'Entrée spécimen (table large)', 'Le partID du spécimen utilisé dans un nom large.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('fraspecimenName', 'fra', 'specimenName', 'Nom de l''échantillon (tableau large)', 'Le spécimen référencé pour le nom large.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('fraspecimens', 'fra', 'specimens', 'Type de partie du spécimen', 'La substance sur laquelle l''observation a été faite.', 'Voir partID = specimentID', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspecimenSet', 'fra', 'specimenSet', 'En-tête de l''ensemble d''échantillons', 'Identification d''un ensemble de spécimens pouvant être utilisés pour une mesure ou une méthode.', 'NA', '2.2.2', '2.2.2', 'added in 2.2.2', NULL),
  ('fraspecimenSets', 'fra', 'specimenSets', 'Ensemble de spécimens', 'L''ensemble des spécimens valides qui s''appliquent à une partie donnée.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspeed', 'fra', 'speed', 'Classe de vitesse', 'Measures and methods relating to speed.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspeedUnitSet', 'fra', 'speedUnitSet', 'Ensemble d''unités de vitesse', 'Unité définie pour la déclaration des vitesses (vitesse de centrifugation, etc.)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('fraspike', 'fra', 'spike', 'Matrice d''ensemencement et récupération', 'Méthode d''évaluation de l''inhibition par matrice d''ensemencement et récupération.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspikeConc', 'fra', 'spikeConc', 'Concentration du pic', 'Concentration de la cible dans les contrôles de récupération de la matrice (le contrôle de processus).', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('fraspikeMat', 'fra', 'spikeMat', 'Objectif de contrôle de l''efficacité de la récupération', 'rec_eff_spike_matrix', 'NA', '1.0.0', '2.0.0', 'description wording', NULL),
  ('fraspikeMatSet', 'fra', 'spikeMatSet', 'Ensemble de catégories pour matrice enrichie', 'L''ensemble de catégorie pour spikeMat (matrices dans lesquelles la cible de contrôle de l''efficacité de la récupération est injectée).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspikeTarget', 'fra', 'spikeTarget', 'Efficacité de la récupération de la matrice enrichie', 'Méthode spécifiant la cible de contrôle de l''efficacité de récupération. Elle correspond à l''ID de la méthode de la matrice enrichie.', 'Devrait typiquement être indexé comme une étape procédant à l''étape spikeMaterial methodID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspikeTargetSet', 'fra', 'spikeTargetSet', 'Ensemble de catégories pour l''efficacité de la récupération de la matiére enrichie', 'L''ensemble de catégories contenant toutes les catégories valides pour la cible de contrôle de l''efficacité de la récupération (ou de matrice enrichie).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraspill', 'fra', 'spill', 'Échantillon renversé', 'Le contenu de l''échantillon s''est déversé du récipient.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasSludge', 'fra', 'sSludge', 'Boues du décanteur secondaire', 'Boue provenant d''un décanteur secondaire.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('frasss', 'fra', 'sss', 'refuge', 'Autre type d''hébergement des services sociaux', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastabPnd', 'fra', 'stabPnd', 'Étang de stabilisation', 'Spécifie un type de site qui est un bassin conçu et construit pour le traitement des eaux usées afin de réduire le contenu organique et d''éliminer les agents pathogènes des eaux usées.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frastandardConc', 'fra', 'standardConc', 'Classe de concentration standard', 'Spécifie une collection de mesures/méthodes liées aux concentrations standard.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastandardCurve', 'fra', 'standardCurve', 'Classe de courbe standard', 'Mesures et méthodes relatives à la génération ou à l''enregistrement d''une courbe standard.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastaphGrp', 'fra', 'staphGrp', 'Groupe Staphylococcus', 'Un groupe de mesures/méthodes relatives aux bactéries staphylocoques.', 'Utilisé pour décrire les informations sur l''organisme pour les mesures générales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastateProvLevel', 'fra', 'stateProvLevel', 'Départements, États ou provinces', 'Départements, États ou provinces', 'NA', '2.0.0', '3.0.0', 'Reactivated as organization level and sector categorical inputs, rather than attributes.', NULL),
  ('frastateProvReg', 'fra', 'stateProvReg', 'État, province ou région', 'L''état, la province ou la région où se trouve un site ou une organisation ; partie de l''adresse.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frastatus', 'fra', 'status', 'Statut', 'Indique si la partie est toujours active et peut être utilisée dans la version la plus récente de l''ODM. Les valeurs sont "actif" ou "inactif".', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastatusSet', 'fra', 'statusSet', 'Ensemble de catégories de statut', 'Un ensemble de catégories pour partID = status pour indiquer si une partie est en cours d''utilisation ou non.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastdConcentrationUnitSet', 'fra', 'stdConcentrationUnitSet', 'Ensemble d''unités de concentration standard', 'Ensemble d''unités pour les mesures de concentration.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastdCurveMet', 'fra', 'stdCurveMet', 'Standard Curve Calculation Method', 'Décrit l''approche spécifique utilisée pour le calcul d''une courbe standard.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastdCurveSet', 'fra', 'stdCurveSet', 'Ensemble de calcul de la courbe standard', 'L''ensemble contenant toutes les méthodes valides pour les calculs de la courbe standard de la PCR.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastec', 'fra', 'stec', 'Escheria coli producteur de shiga-toxine (STEC)', 'Escheria coli producteur de shiga-toxine (STEC).', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('frasTemp', 'fra', 'sTemp', 'Température de stockage de l''échantillon en degrés Celsius', 'Température à laquelle l''échantillon est stocké en Celsius.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('frastepID', 'fra', 'stepID', 'ID de l''étape du protocole', 'L''identifiant unique pour une étape de méthode spécifique.', 'Les étapes de la méthode sont les éléments constitutifs d''un ensemble de méthodes plus vaste, ces dernières étant liées à des rapports de mesure spécifiques.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastepIDObj', 'fra', 'stepIDObj', 'Index de l''étape de la méthode', 'Spécifie l''index d''une étape de méthode dans un ensemble de méthodes, c''est-à-dire l''ordre des étapes dans un ensemble.', 'Remplissez ce champ en utilisant l''ID d''étape du protocole (partID = stepID). Avec `protocolIDSub` ou `stepIDSub` et `relationshipID`, la relation de protocole est définie comme suit : [protocolIDSubject ou stepIDSubject] [relationshipID] [protocolIDObject ou stepIDObject]. Ex : stepIDSubject précède protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastepIDSub', 'fra', 'stepIDSub', 'Step ID Subject', 'Le sujet de la relation entre une étape du protocole et une autre étape ou un protocole, dans un conteneur d''ID de protocole.', 'Remplissez ce champ en utilisant l''ID d''étape du protocole (partID = stepID). Avec `protocolIDObj` ou `stepIDObj` et `relationshipID`, la relation de protocole est définie comme suit : [protocolIDSubject ou stepIDSubject] [relationshipID] [protocolIDObject ou stepIDObject]. Ex : stepIDSubject précède protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastepProvenanceID', 'fra', 'stepProvenanceID', 'ID parentale de l''étape de la méthode', 'Une étape de méthode qui a servi de base à une autre étape de méthode. Cela peut être dû à des changements de version, ou à la référence à un ensemble de méthodes qui a été adapté par la suite.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastepVer', 'fra', 'stepVer', 'Version de l’étape du protocole', 'Spécifie la version de l''étape de la méthode.', 'Version de la méthode d''analyse. Un versionnement de type sémantique est recommandé.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frastEr', 'fra', 'stEr', 'Erreur standard', 'L''erreur standard d''une série de mesures.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastercobilin', 'fra', 'stercobilin', 'Stercobiline', 'La stercobiline est un pigment biliaire tétrapyrrolique et l''un des produits finaux du catabolisme de l''hème. C''est le composé chimique responsable de la couleur brune des matières fécales humaines. Elle a été isolée pour la première fois à partir de matières fécales en 1932.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastorTempDef', 'fra', 'storTempDef', 'température de stockage de l''échantillion', 'Tempéraure de stockage par défaut quand un nouvel échantillon est créé pour ce site. Se référer é la colonne "storageTempC" dans la table "Sample"', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('frastoTim', 'fra', 'stoTim', 'Temps de stockage', 'Durée pendant laquelle un échantillon a été stocké.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frastrepGrp', 'fra', 'strepGrp', 'Groupe des streptocoques', 'Un groupe de mesures/méthodes relatives aux bactéries streptocoques.', 'Utilisé pour décrire les informations sur l''organisme pour les mesures générales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frastrepPneu', 'fra', 'strepPneu', 'Streptococcus pneumoniae', 'Streptococcus pneumoniae', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frasu', 'fra', 'su', 'Raccourci du feuillet de synthèse', 'Nom abrégé utilisé pour référencer la feuille de synthèse du fichier dictionary.xlxs.', 'feuille d''appuie ', '2.2.2', '3.0.0', 'depreciated in version 3', NULL),
  ('frasubVar', 'fra', 'subVar', 'Sous-variante ou lignée', 'Unité utilisée pour signaler une lignée génétique spécifique, ou pour préciser qu''une variante signalée est une sous-variante d''une autre.', 'A utiliser en combinaison avec un ID de mesure de variante pour spécifier la filiation ; ex : measureID = Omicron, valeur = BA.2, unité = subvar', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #120', NULL),
  ('frasuc', 'fra', 'suc', 'Sucralose', 'Sucralose (habituellement mesuré en tant qu''indicateur chimique fécal humain)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frasum14', 'fra', 'sum14', 'Somme mobile des 14 derniers jours', 'La somme mobile du nombre de cas ou d''un certain type de comptage au cours des 14 jours précédents.', 'Agrégation pour une mesure de population ou de maladie afin d''expliquer les effets cliniques au niveau de la population.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('frasumm', 'fra', 'summ', 'Résumé', 'Bréve description de la méthode d''analyse et de comment celle-ci différe d''autres méthodes.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('frasummary', 'fra', 'summary', 'Résumé de la feuille de travail', 'Fiche de synthèse du fichier dictionnaire.xlxs.', 'La fiche de synthèse contient le versioning et le changelog.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasunny', 'fra', 'sunny', 'Ensoleillé', 'CatSetégorie qualitative pour la mesure météorologique, spécifiant une journée claire et ensoleillée.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('frasurf', 'fra', 'surf', 'Surface', 'Une mesure ou une observation faite à partir d''une substance sur une surface.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasurface', 'fra', 'surface', 'Autre surface', 'Surface autre que le sol ou le bureau.', 'Voir aussi les catégories pour le sol et le bureau. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasurfaceCompartmentSet', 'fra', 'surfaceCompartmentSet', 'Ensemble de compartiments de surface', 'Un ensemble de compartiments pour les mesures et les méthodes dans le compartiment de la surface.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasurfaceWaterCompartmentSet', 'fra', 'surfaceWaterCompartmentSet', 'Ensemble de compartiments d’eau et de surface.', 'Un ensemble de compartiments pour les mesures et les méthodes dans les compartiments de la surface ou de l''eau.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frasurfSw', 'fra', 'surfSw', 'Écouvillon de surface', 'Écouvillon de surface.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraswgTrck', 'fra', 'swgTrck', 'Camion à eaux usées', 'Camion de vidange.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('fraswrSed', 'fra', 'swrSed', 'Sédiment d’égout', 'Sédiments provenant des égouts.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('fraswrSet', 'fra', 'swrSet', 'Zone de captage d''un réseau d''égout', 'Zone de captage d''un réseau d''égout', 'NA', '1.0.0', '2.0.0', 'Name Change (from Polygon Type)', NULL),
  ('frasynthetic', 'fra', 'synthetic', 'Échantillon synthétique', 'Un échantillon synthétique ou généré artificiellement.', 'Les échantillons synthétiques sont créés artificiellement en mélangeant des quantités connues de substances ou d''organismes cibles avec de l''eau propre, souvent en laboratoire. Ces échantillons sont utilisés comme contrôles, points de référence ou normes d''étalonnage au cours du processus d''analyse afin de garantir des résultats précis et fiables. Par exemple, un échantillon synthétique contenant une concentration connue d''un polluant spécifique peut être utilisé pour calibrer l''équipement analytique ou pour tester l''efficacité d''une nouvelle méthode de détection.', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('frat19r', 'fra', 't19r', 'Gène cible de la variante delta t19r', 'Gène cible t19r de la variante delta.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frat3646a', 'fra', 't3646a', 'Gène cible de la variante delta t3646a', 'Gène cible t3646a de la variante delta.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frat547k', 'fra', 't547k', 'Gène cible de la variante omicron t547k', 'Gène cible t547k de la variante omicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frat9i', 'fra', 't9i', 'Gène cible de la variante omicron t9i', 'Gène cible t9i de la variante omicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratables', 'fra', 'tables', 'Type de partie de tables', 'Le type de partie pour les tables, qui stockent les enregistrements de mesures, de méthodes et d''attributs pour faciliter la création de rapports.', 'Un exemple de table est `site`, une collection d''attributs tels que le nom et l''adresse du site pour décrire l''endroit où les échantillons environnementaux sont prélevés. PHES-ODM dispose de tables de rapport, mais les utilisateurs peuvent également créer leurs propres tables.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratableSet', 'fra', 'tableSet', 'Ensemble de catégories de colonnes de table', 'L''ensemble des catégories pour les entrées valides dans les colonnes des tableaux.', 'Ces catégories sont utilisées dans la liste des parties pour des colonnes portant le nom de tables afin d''indiquer la position et la fonction d''une partie donnée dans le diagramme entité-relation du modèle de données.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratableSupport', 'fra', 'tableSupport', 'Assistance aux tables', 'Parties conçues pour prendre en charge la définition des métadonnées des tables dans la table des parties.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frataqpatN', 'fra', 'taqpatN', 'Gène cible de SRAS-CoV-2 TaqPath N', 'Gène cible TaqPath N de SRAS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frataqpatS', 'fra', 'taqpatS', 'Gène cible de SRAS-CoV-2 TaqPath S', 'Gène cible TaqPath N de SRAS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratemp', 'fra', 'temp', 'Température d''eau', 'la température de l''échantillon au moment oé la mesure est prise, souvent é son arrivée au laboratoire.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('fratemperature', 'fra', 'temperature', 'Classe de température.', 'Spécifie un ensemble de mesures/méthodes liées à la température.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratemperatureUnitSet', 'fra', 'temperatureUnitSet', 'Ensemble d''unités de température', 'Ensemble d''unités pour les mesures de température.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratemplateSheetSet', 'fra', 'templateSheetSet', 'Ensemble de feuilles modèles', 'Feuilles de calcul dans le modèle de surveillance ODM générique complet (tous les tableaux).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratempSet', 'fra', 'tempSet', 'Ensemble de modèles', 'L''ensemble organisateur pour les modèles.', 'NA', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('fratempType', 'fra', 'tempType', 'Acide nucléique Type de modèle', 'Indique si une PCR ou un séquençage a utilisé de l''ARN ou de l''ADN comme matrice pour la réaction.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('fratempVol', 'fra', 'tempVol', 'Volume de la matrice d''acide nucléique', 'Le volume de la matrice d''ADN ou d''ARN utilisée pour la PCR. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraterminal', 'fra', 'terminal', 'Terminal de l''aéroport', 'Type de catégorie du bassin d''échantillonnage du terminal de l''aéroport', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
