  ('fratp24s', 'fra', 'tp24s', 'Echantillon 24 heures proportionnel au temps', 'Un échantillon composite proportionnel au temps prélevé sur 24 heures, généralement prélevé par un auto-échantilonneur.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('fratPallidum', 'fra', 'tPallidum', 'Treponema pallidum', 'Treponema pallidum', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
