  ('spaanaplasmaGrp', 'spa', 'anaplasmaGrp', 'Grupo Anaplasma', 'Grupo de medidas/métodos relacionados con bacterias anaplasma.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaandBoo', 'spa', 'andBoo', 'Agregación booleana AND', 'Agregación "Y" - Agregación "Y".', 'Si todos los valores de la agregación son «TRUE», la agregación AND también es «TRUE». Si todos los valores de la agregación son «FALSE», la agregación AND también es «TRUE». ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaanneal', 'spa', 'anneal', 'hibridación/extensión', 'Describe el ciclo de hibridación y/o extensión en un proceso PCR.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaanyCompartmentSet', 'spa', 'anyCompartmentSet', 'Cualquier conjunto de compartimentos', 'Conjunto de compartimento para medidas y métodos en cualquier compartimento.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaanySpecimenSet', 'spa', 'anySpecimenSet', 'Cualquier conjunto de especímenes', 'Conjunto de especímenes que incluye cualquier espécimen.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
