  ('spabrsvCul', 'spa', 'brsvCul', 'Diana de cultivo brsv', 'El virus respiratorio sincitial bovino (BRSV) cultivado se utiliza como objetivo de control de la eficiencia de recuperación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spabrsvN', 'spa', 'brsvN', 'BRSV-N', 'Región del gen de la proteína de la cápside del virus respiratorio sincitial bovino', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
