INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('spaCalprotectin', 'spa', 'Calprotectin', 'Calprotectina', 'La calprotectina es una proteína de la familia S-100 que se une al calcio y al zinc y se encuentra principalmente en los neutrófilos y en todo el cuerpo humano. La presencia de calprotectina en las heces es consecuencia de la migración de neutrófilos al tejido gastrointestinal debido a un proceso inflamatorio.', 'NA', '2.2.0', '3.0.0', 'officially activate in v 3.0.0', NULL),
  ('spacamp', 'spa', 'camp', 'Campylobacter', 'Campylobacter.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacampGrp', 'spa', 'campGrp', 'Grupo Campylobacter', 'Grupo de medidas/métodos relacionados con la bacteria Campylobacter.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacapacity', 'spa', 'capacity', 'Clase de capacidad', 'Medidas y métodos relacionados con la capacidad.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacapacityUnitSet', 'spa', 'capacityUnitSet', 'Conjunto de unidades de capacidad', 'Conjunto de unidades para mediciones de capacidad.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacapitalEndonym', 'spa', 'capitalEndonym', 'Endónimo de ciudad capital', 'Nombre que utilizan los lugareños para referirse a la capital de su país.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacapitalExonym', 'spa', 'capitalExonym', 'Exónimo de ciudad capital', 'Nombre en inglés que utilizan los extranjeros para referirse a la capital del país.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacaRepDate', 'spa', 'caRepDate', 'Fecha de informe de caso', 'Fecha en la que se hicieron públicos los datos. Por lo general, los datos comunicados y esta medida son los que se comunican y utilizan con mayor frecuencia.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('spacaseEpDate', 'spa', 'caseEpDate', 'Fecha de episodio de casos confirmados', 'La fecha del episodio es la fecha más temprana de inicio, prueba o notificación de un caso confirmado.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spacaseOnDate', 'spa', 'caseOnDate', 'Fecha de inicio de casos confirmados', 'La fecha más temprana en la que se notificaron los síntomas de un caso confirmado. A menudo, estos datos se desconocen y no se notifican. En su lugar, se utiliza el episodio.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spacaseRepDate', 'spa', 'caseRepDate', 'Fecha de informe de casos confirmados', 'Fecha en la que se notificaron públicamente las cifras de un caso confirmado. Por lo general, los datos notificados y esta medida son los que se notifican y utilizan con mayor frecuencia.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spacaseTestDate', 'spa', 'caseTestDate', 'Fecha de prueba de casos confirmados', 'Fecha en la que se realizó la prueba de COVID-19 para un caso confirmado.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spacategorical', 'spa', 'categorical', 'Tipo de datos categórico', 'Tipo de datos para datos categóricos.', 'Solo se utiliza para las entradas del diccionario de piezas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacategories', 'spa', 'categories', 'Categorías', 'Lista discreta de valores que se pueden notificar para una medida, método o atributo.', 'Un ejemplo de uso de las categorías sería cómo se utilizan para registrar el lugar donde se toma una medida (partID = geoType). Para el atributo geoType hay diferentes tipos de sitios donde se pueden tomar muestras: una planta de tratamiento de aguas residuales, un tanque de almacenamiento de aviones, una estación de bombeo de aguas residuales, etc. Cada uno de estos tipos de sitios se registra como una categoría que se puede identificar en categorySetID = sTypeCatSets', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacAuris', 'spa', 'cAuris', 'Candida auris', 'Especie de levadura Candida auris, o C. auris.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
