  ('spacPerfrigens', 'spa', 'cPerfrigens', 'Clostridium perfringens', 'Clostridium perfringens.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacphDate', 'spa', 'cphDate', 'Fecha de medición de la población con Covid-19', 'Fecha de notificación de la medida contra la COVID-19.', 'Depreciado en la versión 2 de ODM. La identificación de la medida es ahora measureReportID con fechas de informe como para cualquier informe de medida. ', '1.0.0', '2.0.0', 'depreciated, measure identication is now found in partID = measureRepID, with date fields for any measure report. ', NULL),
  ('spacphid', 'spa', 'cphid', 'ID del CPHD', 'Identificador único de la tabla.', 'Depreciado en la versión 2 de ODM. La identificación de la medida es ahora measureReportID. ', '1.0.0', '2.0.0', 'depreciated, measure identication is now found in partID = measureRepID', NULL),
