  ('spaeluate', 'spa', 'eluate', 'Eluato/Material filtrado resuspendido retenido', 'La fracción de eluido, o material resuspendido de la filtración, se retiene después de la separación sólida/centrifugación.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaelutionBuff', 'spa', 'elutionBuff', 'Tampón de elución', 'Se utiliza un tampón de elución para resuspender el material.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaemail', 'spa', 'email', 'Correo electrónico de contacto', 'Dirección de correo electrónico de contacto del laboratorio.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaenaForm', 'spa', 'enaForm', 'Formato ENA', 'El conjunto de datos se registró y/o almacenó originalmente en formato ENA.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaenaMap', 'spa', 'enaMap', 'Asociación Europea de Nucleótidos Columna de mapeo', 'Encabezado ENA.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaenaNotes', 'spa', 'enaNotes', 'Asociación Europea de Nucleótidos (ENA) - notas', 'Notas ENA.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
