  ('spaenvSnwD', 'spa', 'envSnwD', 'Profundidad de la nieve en el suelo', 'Profundidad total de la nieve en el suelo.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spaenvSnwF', 'spa', 'envSnwF', 'Nevadas', 'Nevada, es decir, cantidad de precipitación en forma de nieve.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spaepec', 'spa', 'epec', 'Escherichia coli enteropatógena (EPEC)', 'Escherichia coli enteropatógena (EPEC)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaepiDate', 'spa', 'epiDate', 'Fecha del episodio', 'La fecha del episodio es la más temprana de las fechas de inicio, prueba o notificación.', 'NA', '1.0.0', '2.0.0', 'depreciate', NULL),
  ('spaepl10', 'spa', 'epl10', 'Licencia pública Eclipse 1.0', 'La licencia de la medida o el conjunto de datos se gestiona bajo la Licencia Pública Eclipse 1.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaepl20', 'spa', 'epl20', 'Licencia pública Eclipse 2.0', 'La licencia de la medida o el conjunto de datos se gestiona bajo la Licencia Pública Eclipse 2.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaerdTableSet', 'spa', 'erdTableSet', 'Conjunto de tablas ERD', 'Todas las tablas que figuran en el diagrama de relaciones entre entidades. ', 'El modelo ODM completo se conoce comúnmente como tablas «largas», ya que almacena datos con una medida por fila.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaeSarbec', 'spa', 'eSarbec', 'Gen E sars-cov-2 específico del sarbecovirus', 'Gen objetivo específico del sarbecovirus sars-cov-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaesbl', 'spa', 'esbl', 'Genes codificadores de ESBL', 'Genes que codifican beta-lactamasas de espectro ampliado.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spaesp', 'spa', 'esp', 'Preparación de muestras basada en exclusiones (ESP)', 'Preparación de muestras basada en exclusiones (ESP).', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaestFreqReads', 'spa', 'estFreqReads', 'Frecuencia estimada de lecturas', 'Frecuencia estimada de lecturas en un ensayo de secuenciación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaestuary', 'spa', 'estuary', 'Estuario, masa de agua natural', 'Estuario, masa de agua natural.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
