  ('spaeupl12', 'spa', 'eupl12', 'Licencia pública de la Unión Europea 1.2', 'La licencia de la medida o el conjunto de datos se gestiona bajo la Licencia Pública de la Unión Europea 1.2.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaexceptions', 'spa', 'exceptions', 'Tipo de parte de excepciones', 'Tipo de parte excepcional para su uso en la creación de nombres amplios que no siguen la estructura general.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaexpec', 'spa', 'expec', 'Escherichia coli patógena extraintestinal (ExPEC)', 'Escherichia coli patógena extraintestinal (ExPEC).', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaexpFail', 'spa', 'expFail', 'Experimento fallido', 'El experimento de PCR falló. No se ha comunicado ningún valor.', 'El valor debe estar en blanco para una medida con este valor de qualityFlag.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaextBlank', 'spa', 'extBlank', 'Extracción en blanco - Control', 'Indicador binario S/N para indicar si se utilizó una muestra en blanco como control para el proceso de extracción de ácido nucleico.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
