  ('spaextraction', 'spa', 'extraction', 'Método de extracción de ácido nucleico', 'Descripción del método de extracción de ácido nucleico.', 'Descripción del método utilizado para extraer la muestra', '1.0.0', '2.0.0', 'description wording add categories from NWSS', NULL),
  ('spaextractSet', 'spa', 'extractSet', 'Conjunto de extracción de ácido nucleico', 'Conjunto utilizado para almacenar todos los valores válidos de la categoría para el método de extracción de ácido nucleico.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaexvol', 'spa', 'exvol', 'Volumen de extracción de la muestra', 'Volumen de extracción de la muestra.', 'Tamaño de la muestra analizada.', '1.0.0', '2.0.0', 'description wording and unit set', NULL),
  ('spaf456l', 'spa', 'f456l', 'Mutación F456L', 'La mutación variante FLiRT/SLip F456L.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
