INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('spahum', 'spa', 'hum', 'Compartimento humano', 'Una medida u observación realizada sobre un ser humano.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spahumanCompartmentSet', 'spa', 'humanCompartmentSet', 'Conjunto de compartimentos humanos', 'Un compartimento establecido para medidas y métodos en el compartimento humano.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spahumid', 'spa', 'humid', 'Clase de humedad', 'Medidas y métodos relacionados con la humedad.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spahUn', 'spa', 'hUn', 'Véase el encabezado para la unidad', 'Indicador para mostrar en un nombre amplio que la información de la unidad se encuentra en una columna diferente.', 'Valor no válido para la unidad en el formato largo estándar.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spai1566v', 'spa', 'i1566v', 'i1566v gen objetivo de la variante ómicron', 'i1566v objetivo del gen de mutación de la variante ómicron', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spai3758v', 'spa', 'i3758v', 'i3758v gen objetivo de la variante ómicron', 'i3758v objetivo del gen de mutación de la variante ómicron', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spai82t', 'spa', 'i82t', 'i82t gen objetivo de la variante delta', 'i82t objetivo del gen de mutación de la variante delta', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaibu', 'spa', 'ibu', 'Ibuprofeno', 'Ibuprofeno (normalmente medido como indicador químico fecal humano)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaicd', 'spa', 'icd', 'Clasificación Internacional de Enfermedades', 'Sistema de clasificación de enfermedades en humanos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaicu', 'spa', 'icu', 'Pacientes de la unidad de cuidados intensivos', 'Unidades para describir una medida poblacional de pacientes que se encuentran en cuidados intensivos debido a una causa determinada.', 'Unidad para una medida de población o enfermedad que explica los efectos clínicos a nivel de población.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spain', 'spa', 'in', 'Tabla de instrumentos Abreviaturas', 'Abreviatura utilizada para referirse a la tabla que contiene información sobre los instrumentos.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaindex', 'spa', 'index', 'Índice', 'Número índice en caso de que la medición se haya realizado varias veces.', 'NA', '1.1.0', '2.0.0', 'NA', NULL),
  ('spaindusIn', 'spa', 'indusIn', 'Aportación industrial', 'Porcentaje del total de aguas residuales procedentes de fuentes industriales.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spainfluEqui', 'spa', 'influEqui', 'Equilibrio de afluentes', 'Indicador binario que indica si un emplazamiento almacena las aguas residuales afluentes antes de su tratamiento para equilibrar los caudales.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spainhibitionSet', 'spa', 'inhibitionSet', 'Conjunto de inhibición', 'Categoría establecida para los métodos de inhibición.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spainhibMe', 'spa', 'inhibMe', 'Medida de inhibición', 'Parámetro para informar de si se ha detectado o no inhibición en la muestra.', 'Detectado = VERDADERO, no detectado = FALSO.', '1.1.0', '2.0.0', 'structure change', NULL),
  ('spainhibMeth', 'spa', 'inhibMeth', 'Método de inhibición', 'Descripción del método utilizado para evaluar la inhibición molecular.', 'Descripción de los parámetros de inhibición.', '1.0.0', '2.0.0', 'structure change', NULL),
  ('spainnovaprepUF', 'spa', 'innovaprepUF', 'Ultrafiltración Innovaprep', 'Ultrafiltración Innovaprep', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spainput', 'spa', 'input', 'Entrada', 'Entrada para una tabla. Indica si una parte se puede utilizar en una tabla.', '«Entrada» se utiliza para indicar si una parte se puede utilizar como entrada en una tabla (algo con partType = tabla). Por ejemplo, covN1 es una medida específica que se puede introducir en el campo measureID de la tabla de medidas. Por lo tanto, covN1 tiene un valor «entrada» en la columna de medidas de la lista de partes. Los usuarios de ODM pueden generar su propia plantilla personalizada modificando el valor «input» solo para las partes que sean aplicables a su programa.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spains214epe', 'spa', 'ins214epe', 'Variante Ómicron ins214epe Inserción', 'Omicron Variant ins214epe Mutación por inserción.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spainstrumentID', 'spa', 'instrumentID', 'ID del instrumento', 'Identificador único de un instrumento.', 'NA', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('spainstruments', 'spa', 'instruments', 'Tabla de instrumentos', 'Tabla que contiene información sobre los instrumentos.', 'adaptado de la documentación de la versión 1', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spainstrumentsOrder', 'spa', 'instrumentsOrder', 'Orden de las columnas de la tabla de instrumentos', 'Especifica el orden de las columnas en la tabla Instrumentos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spainstrumentsRequired', 'spa', 'instrumentsRequired', 'Encabezados obligatorios de la tabla de instrumentos', 'Especifica las columnas necesarias en la tabla Instrumentos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spainstrumentTypeOther', 'spa', 'instrumentTypeOther', 'Otro instrumento', 'Tipo de instrumento distinto de los incluidos en el PHES-ODM.', 'Otro tipo de instrumento de medición. Añadir descripción a las notas. Consulte la documentación para saber cómo solicitar la incorporación de nuevos instrumentos al diccionario. ', '1.0.0', '2.0.0', 'description wording, structure, one of the two "other" field that was not depricated in the transition from V1 to V2', NULL),
  ('spainsType', 'spa', 'insType', 'Tipo de instrumento', 'Tipo de instrumento utilizado para realizar la medición.', 'NA', '1.0.0', '2.0.0', 'none', NULL),
  ('spainsTypeOth', 'spa', 'insTypeOth', 'Describir otro tipo de instrumento, si procede', 'Descripción del instrumento en caso de que no figure en instrumentType.', 'NA', '1.0.0', '2.0.0', 'none, one of the two "other" field that was not depricated in the transition from V1 to V2', NULL),
  ('spainsTypeSet', 'spa', 'insTypeSet', 'Conjunto de instrumentos', 'Lista de instrumentos que se utilizan para las medidas y métodos', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaintAMRGrp', 'spa', 'intAMRGrp', 'Grupo de resistencia antimicrobiana de la integrasa', 'El grupo de medidas y métodos relacionados con la resistencia antimicrobiana relacionada con la integrasa.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spainteger', 'spa', 'integer', 'Tipo de datos enteros', 'El tipo de datos para números enteros.', 'Solo se utiliza para las entradas del diccionario de partes.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaintegraseCl1', 'spa', 'integraseCl1', 'Gen diana de la integrasa de clase I', 'Gen diana de la resistencia antimicrobiana de la integrasa.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spainter', 'spa', 'inter', 'Intercepción', 'Valor de intersección de la curva de calibración.', 'Se utiliza para almacenar información sobre curvas de calibración, aunque también puede ser aplicable a otros tipos de curvas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaip2ip4', 'spa', 'ip2ip4', 'Gen diana combinado ip2 e ip4 sars-cov-2', 'Gen diana combinado ip2 e ip4 sars-cov-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaisc', 'spa', 'isc', 'ISC', 'La licencia de la medida o el conjunto de datos se gestiona bajo la licencia ISC.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaiso6391', 'spa', 'iso6391', 'ISO639-1', 'Primera parte de la serie ISO 639 de normas internacionales para códigos de idiomas. La parte 1 cubre el registro de códigos de dos letras. En junio de 2021 hay 183 códigos de dos letras registrados. Los códigos registrados cubren los principales idiomas del mundo.', 'Parte de los metadatos de un languageID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaiso6392B', 'spa', 'iso6392B', 'ISO639-2B', 'Conjunto de normas internacionales que enumeran códigos cortos para los nombres de los idiomas. Estos ISO639-2 son los códigos de tres letras definidos en la segunda parte (ISO 639-2) de la norma, incluidos los códigos de dos letras correspondientes (ISO 639-1) cuando existen. La «B» especifica el código bibliográfico (código B).', 'Parte de los metadatos de un languageID.', '2.0.0', '3.0.0', 'removed from languages table to avoid duplication of identical values across columns.', NULL),
  ('spaiso6392T', 'spa', 'iso6392T', 'ISO639-2T', 'Conjunto de normas internacionales que recogen códigos cortos para los nombres de los idiomas. Estos códigos ISO 639-2 son los códigos de tres letras definidos en la segunda parte (ISO 639-2) de la norma, incluidos los códigos de dos letras (ISO 639-1) correspondientes, cuando existen. La «T» especifica el código terminológico (código T).', 'Parte de los metadatos de un languageID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaiso6393', 'spa', 'iso6393', 'ISO639-3', 'Conjunto de normas internacionales que recogen códigos cortos para los nombres de los idiomas. ISO 639-3 amplía los códigos alfa-3 de ISO 639-2 con el objetivo de abarcar todos los idiomas naturales conocidos. ', 'Parte de los metadatos de un languageID.', '2.0.0', '3.0.0', 'removed from languages table to avoid duplication of identical values across columns.', NULL),
  ('spaiso6396', 'spa', 'iso6396', 'ISO639-6', 'Conjunto de normas internacionales que recogen códigos abreviados para los nombres de los idiomas. ISO 639-6 se basa en ISO639-3 con el uso de códigos de cuatro letras, lo que permite a los usuarios diferenciar entre variantes de idiomas y familias lingüísticas, como las versiones históricas y las versiones recuperadas de los idiomas.', 'Parte de los metadatos de un languageID.', '2.0.0', '3.0.0', 'removed from languages table to avoid duplication of identical values across columns.', NULL),
  ('spaisoCode', 'spa', 'isoCode', 'Código de país ISO 3166-1 alfa-2', 'El código ISO 3166-1 alfa-2, un código de país de dos letras que también se utiliza para crear el código de subdivisión de país ISO 3166-2 y el dominio de nivel superior de país en Internet.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '3.0.0', 'removed as a "template" input in addresses, as is a synonym for the "country" field anyway.', NULL),
  ('spaisoCodeX', 'spa', 'isoCodeX', 'Código de país ISO 3166-1 alfa-3', 'El código ISO 3166-1 alfa-3, un código de país de tres letras que puede permitir una mejor asociación visual entre el código y los nombres de los países que el código 3166-1 alfa-2.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spaisoZone', 'spa', 'isoZone', 'Código ISO 3166-2 para subdominio de país', 'Los códigos ISO 3166-2 para los nombres de las principales subdivisiones (por ejemplo, provincias, estados, departamentos, regiones) de todos los países codificados en ISO 3166-1.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '3.0.0', 'removed as a "template" input in addresses, as is a synonym for the "stateProvReg" field anyway.', NULL),
  ('spajn17V', 'spa', 'jn17V', 'Variante JN.1.7', 'La variante JN.1.7 del SARS-CoV-2, una de las variantes FLiRT.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spajn1V', 'spa', 'jn1V', 'Variante JN.1', 'La variante JN.1 es una subvariante de la variante Ómicron BA.2.86 y contiene varias mutaciones asociadas con el escape de la protección inmunitaria mediada por la vacuna. El origen de las variantes FLiRT del SARS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spak856r', 'spa', 'k856r', 'Gen objetivo de la variante omicron k856r', 'Gen diana de la mutación de la variante Ómicron k856r', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
