  ('spakp1V', 'spa', 'kp1V', 'Variante KP.1', 'La variante KP.1 del SARS-CoV-2, una de las variantes FLiRT.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spakp2V', 'spa', 'kp2V', 'Variante KP.2', 'La variante KP.2 del SARS-CoV-2, una de las variantes FLiRT.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
