  ('spalowerCI95', 'spa', 'lowerCI95', 'Límite inferior de un intervalo de confianza del 95 %', 'Especifica el límite inferior de un intervalo de confianza del 95 %.', 'Normalmente debe estar vinculado a un límite superior y a alguna indicación de la dispersión de los datos (es decir, la desviación estándar) y una medida de la media/mediana.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spalowQualSeq', 'spa', 'lowQualSeq', 'Secuencia de baja calidad', 'Secuencia de baja calidad.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('spalowSNRatio', 'spa', 'lowSNRatio', 'Baja relación señal-ruido', 'Baja relación señal-ruido.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('spalowVol', 'spa', 'lowVol', 'Muestra de bajo volumen', 'La muestra es de bajo volumen, pero se analizó de todos modos. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spalPGC', 'spa', 'lPGC', 'Bajo porcentaje de genoma capturado', 'Solo capturó un porcentaje pequeño/bajo del genoma. ', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('spalppa24s', 'spa', 'lppa24s', 'Variante Ómicron Mutación LPPA24S', 'Mutación LPPA24S de la variante Ómicron', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spalppl13c', 'spa', 'lppl13c', 'Licencia pública del proyecto LaTeX v1.3c', 'La licencia de la medida o el conjunto de datos se gestiona bajo la Licencia Pública del Proyecto LaTeX v1.3c.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaltcf', 'spa', 'ltcf', 'Centro de cuidados a largo plazo', 'Centro residencial de atención médica que proporciona atención médica las 24 horas del día. También se denominan centros de enfermería especializada.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaltcfAl', 'spa', 'ltcfAl', 'Cuidados a largo plazo: residencia asistida o residencia de ancianos', 'Centro residencial que proporciona asistencia para el cuidado diario, pero que generalmente no ofrece cuidados de enfermería especializada. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaltcfO', 'spa', 'ltcfO', 'Otros cuidados a largo plazo', 'Otros centros residenciales que proporcionan cuidados diarios y/o médicos, pero que no se definen como residencias de ancianos/centros de enfermería especializada o centros de vida asistida. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaltDpcr', 'spa', 'ltDpcr', 'Tecnologías de la vida PCR digital', 'Describe un análisis de PCR realizado con la tecnología de PCR digital de Life Technologies.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
