  ('spameasles', 'spa', 'measles', 'Sarampión', 'Sarampión', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spameaslesGrp', 'spa', 'measlesGrp', 'Grupo del sarampión', 'Grupo de medidas/métodos relacionados con el virus del sarampión.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spameasOth', 'spa', 'measOth', 'Otra medida', 'Otra medida, no especificada en medidas.', 'Añadir descripción a la categoría «Otros».', '1.0.0', '2.0.0', 'Depreciated in version 2 with all "other" fields', NULL),
  ('spameasQualitySet', 'spa', 'measQualitySet', 'Conjunto de calidad de medidas', 'Conjunto de calidad para cualquier medida, incluye todas las opciones de indicadores de calidad para cualquier medida.', 'Se utiliza como un «conjunto de cualidades cualquiera» para las medidas, pero excluye los indicadores de calidad de la muestra para evitar confusiones y errores en la introducción de datos.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasure', 'spa', 'measure', 'Medida', 'Medición u observación de cualquier sustancia, incluidas sustancias biológicas, físicas o químicas.', 'Una medida se registra a partir de una muestra (es decir, un lugar, una muestra, una persona o una población). Las medidas se organizan en grupos y clases (subgrupos).', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasureInput', 'spa', 'measureInput', 'Entrada de medida (tabla amplia)', 'El ID de la parte para la medida que se utiliza en un nombre amplio.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spameasureLic', 'spa', 'measureLic', 'Licencia de medida', 'Especifica la licencia de acceso y uso para una medida única determinada.', 'Rellenado por partID = licenseID', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasurements', 'spa', 'measurements', 'Medidas', 'El atributo para describir un tipo de parte de medidas. Todas las medidas tienen «partType» = «measure». ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasureName', 'spa', 'measureName', 'Nombre de la medida (tabla amplia)', 'La medida a la que se hace referencia para el nombre amplio.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spameasureRepID', 'spa', 'measureRepID', 'ID del informe', 'Identificador único para una medida.', 'Los ID de informe no se pueden repetir.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasures', 'spa', 'measures', 'Tabla de informes de medidas', 'La tabla que contiene información y detalles sobre una medida determinada.', 'Adaptado de la documentación de la versión 1', '1.0.0', '2.0.0', 'combined all measures tables into a single table', NULL),
  ('spameasureSetRepID', 'spa', 'measureSetRepID', 'ID del conjunto de informes del conjunto de medidas', 'Identificador único que vincula un grupo de medidas relacionadas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasureSets', 'spa', 'measureSets', 'Tabla de informes de conjuntos de medidas.', 'La tabla que identifica conjuntos de medidas.', 'Algunos ejemplos de conjuntos de medidas son un conjunto de réplicas, diluciones (utilizadas para generar una curva Ct) o variantes identificadas en una sola muestra.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spameasureSetsOrder', 'spa', 'measureSetsOrder', 'Orden de las columnas de la tabla de conjuntos de medidas.', 'Especifica el orden de las columnas en una tabla de conjuntos de medidas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
