  ('spameOthDe', 'spa', 'meOthDe', 'Otra medida Descripción', 'Descripción de otra medida (measOtherDesc).', 'NA', '1.0.0', '2.0.0', 'Depreciated in version 2 with all "other" fields', NULL),
  ('spames', 'spa', 'mes', 'Medidas Tipo de parte Abreviatura', 'Nombre abreviado utilizado para hacer referencia al atributo que describe un tipo de medida. Todas las medidas tienen `partType` = «measurements». ', 'Tipo de pieza', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spamet', 'spa', 'met', 'Métodos Tipo de parte Abreviatura', 'Nombre abreviado utilizado para hacer referencia a los procedimientos o pasos para recoger muestras o realizar medidas.', 'Tipo de pieza', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spametaboliteGrp', 'spa', 'metaboliteGrp', 'Grupo de metabolitos', 'Grupo de medidas/métodos relacionados con los metabolitos.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spamethod', 'spa', 'method', 'Método', 'Procedimiento para recoger una muestra o realizar una medida.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spamethodConc', 'spa', 'methodConc', 'Método de concentración', 'Descripción del método para concentrar una muestra de aguas residuales.', 'Descripción del método utilizado para concentrar la muestra.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spamethodConcSet', 'spa', 'methodConcSet', 'Conjunto de métodos de concentración', 'Un conjunto de métodos de concentración.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spamethodInput', 'spa', 'methodInput', 'Entrada del método (tabla amplia)', 'El partID del método utilizado en un nombre amplio.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spamethodName', 'spa', 'methodName', 'Nombre del método (tabla amplia)', 'El método al que se hace referencia para el nombre amplio.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spamethods', 'spa', 'methods', 'Métodos', 'Procedimientos o pasos para recoger muestras o realizar mediciones.', 'Por ejemplo, «methodExtract» es un método que describe cómo se extrajo una muestra.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
