  ('spaor', 'spa', 'or', 'abreviatura de tabla de organización', 'Nombre abreviado utilizado para hacer referencia a la tabla que contiene información sobre un laboratorio.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaorb', 'spa', 'orb', 'otro edificio habitacional', 'Edificios residenciales individuales o instituciones no incluidos en otras categorías.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaorBoo', 'spa', 'orBoo', 'agregación booleana OR', 'Agregación «OR».', 'Si cualquier valor de la agregación es «TRUE», entonces la agregación OR también es «TRUE». Si todos los valores de la agregación son «FALSE», entonces la agregación OR también es «FALSE».', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
