  ('spaorganism', 'spa', 'organism', 'organismo', 'Clase de organismo.', 'Identifique la clase = «organismo» cuando una parte identifique un organismo y el tipo de parte = «grupos». Las medidas individuales deben registrarse con una clase para el tipo de medida específico, es decir, alelo, variante, mutación, etc. ', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaorganizationID', 'spa', 'organizationID', 'ID de organización', 'Identificador único de la organización a la que pertenece el informante.', 'NA', '1.1.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaorganizations', 'spa', 'organizations', 'tabla de organización', 'La tabla que contiene información sobre un laboratorio.', 'adaptado de la documentación de la versión 1', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spaorganizationsOrder', 'spa', 'organizationsOrder', 'orden de columnas en tabla de organizaciones', 'Especifica el orden de las columnas en una tabla de organizaciones.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaorganizationsRequired', 'spa', 'organizationsRequired', 'encabezados obligatorios de tabla de organización', 'Especifica las columnas necesarias en una tabla de organizaciones.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaorgLevel', 'spa', 'orgLevel', 'nivel de organización', 'El nivel geográfico de una organización.', 'Hay seis niveles basados en la Clasificación Internacional Normalizada de Unidades Administrativas (ISCU). ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaorgLevelSet', 'spa', 'orgLevelSet', 'conjunto de niveles de organización', 'Categorías de niveles de organización.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
