  ('spasettsol', 'spa', 'settsol', 'Sólidos sedimentados', 'Cantidad de sólidos sedimentados de una muestra de aguas residuales.', 'Puede ser un volumen o un peso; consulte el unitID de una fila de medida determinada para obtener detalles sobre una muestra determinada.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spasetType', 'spa', 'setType', 'Tipo de conjunto', 'El tipo de conjunto. Es decir, conjunto de calidad, conjunto de agregación, conjunto de unidades.', 'NA', '2.0.0', '2.0.0', 'NA', NULL),
  ('spaseverity', 'spa', 'severity', 'Indicador de gravedad', 'Un indicador de la gravedad o seriedad de una bandera de calidad.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
