  ('spaupperCI95', 'spa', 'upperCI95', 'Límite superior del intervalo de confianza del 95%', 'Especifica el límite superior de un intervalo de confianza del 95 %.', 'Una categoría general para los puntos de muestreo de aguas residuales aguas arriba, incluidas las principales tuberías de alcantarillado y estaciones de bombeo.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spaupstream', 'spa', 'upstream', 'Sitios río arriba', 'Un tipo de sitio general para sitios de muestreo de aguas residuales aguas arriba.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('spaureaplasma', 'spa', 'ureaplasma', 'Ureaplasma', 'Ureaplasma', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaureaplasmaGrp', 'spa', 'ureaplasmaGrp', 'Grupo Ureaplasma', 'Un grupo de medidas/métodos relacionados con la bacteria ureaplasma.', 'Se utiliza para describir la información sobre organismos para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaurobilin', 'spa', 'urobilin', 'Urobilina o urocronina', 'La urobilina o urocromo es la sustancia química principal responsable del color amarillo de la orina. Es un compuesto tetrapirrol lineal que, junto con el compuesto incoloro relacionado urobilinógeno, son productos de degradación del hemo tetrapirrol cíclico.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
