  ('spaversion1Variable', 'spa', 'version1Variable', 'Variable ODM V1', 'Variable ODM V1', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavibrio', 'spa', 'vibrio', 'Vibrio', 'Vibrio', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavibrioGrp', 'spa', 'vibrioGrp', 'Grupo Vibrio', 'Un grupo de medidas/métodos relacionados con la bacteria vibrio.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavirusMisc', 'spa', 'virusMisc', 'Grupo de virus diversos', 'Grupo de medidas/métodos relacionados con virus diversos.', 'Los virus diversos se miden a menudo para su normalización o estandarización y solo tienen una medida o método. Cuando un virus tiene muchas medidas, se le asignará su propio ID de grupo en las versiones actualizadas del diccionario.', '1.0.0', '2.2.0', 'Depreciated in V2.0.0', NULL),
  ('spavol', 'spa', 'vol', 'Tamaño en volumen', 'Volumen total de agua o lodos muestreados.', 'Se utiliza para análisis de agua o aire.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavolPr', 'spa', 'volPr', 'Muestra proporcional al volumen', 'Muestra proporcional al volumen, generalmente recogida por un muestreador automático.', '«El muestreo toma el mismo volumen de aguas residuales a intervalos de tiempo variables, después de que un volumen definido de aguas residuales haya pasado por el punto de muestreo. Esto también se denomina volumen constante, tiempo variable (CVVT)».', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavolumeUnitSet', 'spa', 'volumeUnitSet', 'Conjunto de unidades de volumen', 'Conjunto unitario de medidas de volumen.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spavss', 'spa', 'vss', 'Sólidos suspendidos volátiles', 'Sólidos suspendidos volátiles', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavssIg', 'spa', 'vssIg', 'Sólidos suspendidos volátiles – ignición', 'Medida de la calidad del agua, capturada mediante la pérdida por ignición de la masa de sólidos suspendidos totales medidos. Esta ignición se produce generalmente en un horno a una temperatura de 550 °C a 600 °C. Representa la cantidad de materia volátil presente en la fracción sólida de la solución medida.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavsv', 'spa', 'vsv', 'Diana del virus de la estomatitis vesicular (VSV)', 'El virus de la estomatitis vesicular se utiliza como objetivo de control de la eficiencia de recuperación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spavsvABIFor', 'spa', 'vsvABIFor', 'Cebador directo de VSV (ABI)', 'Cebador directo VSV (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavsvABIProbe', 'spa', 'vsvABIProbe', 'Sonda VSV (ABI)', 'Sonda VSV (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavsvABIRev', 'spa', 'vsvABIRev', 'Cebador inverso de VSV (ABI)', 'Cebador inverso VSV (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavsvGrp', 'spa', 'vsvGrp', 'Grupo del virus de la estomatitis vesicular (VSV)', 'Grupo de medidas/métodos relacionados con el virus de la estomatitis vesicular (VSV).', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spavtec', 'spa', 'vtec', 'Escherichia coli productora de verotoxina (VTEC)', 'Escherichia coli productora de verotoxinas (VTEC)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawat', 'spa', 'wat', 'Compartimiento de agua', 'Medida u observación realizada a partir de una sustancia presente en el agua, incluidas las aguas residuales.', 'NA', '1.0.0', '2.0.0', 'Updated', NULL),
  ('spawatConcBuff', 'spa', 'watConcBuff', 'Tampón concentrador de agua (R2042-1)', 'Tampón concentrador de agua (R2042-1)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawater', 'spa', 'water', 'Agua (obsoleto)', 'Agua no residual, procedente de cualquier tipo de masa de agua.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawaterCompartmentSet', 'spa', 'waterCompartmentSet', 'Conjunto de compartimientos de agua', 'Compartimento establecido para medidas y métodos en el compartimento del agua.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawaterQualityGrp', 'spa', 'waterQualityGrp', 'Grupo de calidad del agua', 'Conjunto de medidas/métodos relacionados con la calidad del agua.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawatTemp', 'spa', 'watTemp', 'Temperatura de aguas residuales', 'Temperatura de las aguas residuales.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('spaweath', 'spa', 'weath', 'Clima (al momento del muestreo)', 'Una medida del tiempo capturada a través de categorías cualitativas; parte de un conjunto más amplio de medidas meteorológicas que pueden ser útiles a la hora de recoger muestras de fuentes exteriores.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('spaweather', 'spa', 'weather', 'Clase de clima', 'Medidas y métodos relacionados con el tiempo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaweathSet', 'spa', 'weathSet', 'Conjunto de condiciones climáticas', 'Un conjunto de categorías cualitativas válidas para la medida cualitativa del tiempo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawestNile', 'spa', 'westNile', 'Virus del Nilo Occidental', 'Nilo Occidental', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawgs', 'spa', 'wgs', 'Secuenciación del genoma completo', 'Especifica la estrategia de secuenciación del genoma completo (WGS) para la secuenciación genética.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawho', 'spa', 'who', 'Nomenclatura de la OMS', 'Especifica la nomenclatura variante o genética establecida por la Organización Mundial de la Salud.', 'Si hay varios problemas que señalar, utilice la marca de problemas múltiples y explique los detalles en la sección de notas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawI', 'spa', 'wI', 'Intervalo amplio del 95%', 'El intervalo del 95 % es demasiado amplio, lo que reduce la fiabilidad de los resultados.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawideAttribute', 'spa', 'wideAttribute', 'Atributo especificado (tabla ancha)', 'Identificador único para un atributo solo en una tabla amplia. ', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawideCompartmentSet', 'spa', 'wideCompartmentSet', 'Conjunto de compartimientos para nombres amplios', 'Conjunto de compartimentos para nombres amplios.', 'Para nombres amplios.', '2.2.0', '3.0.0', 'officially activate in v 3.0.0', NULL),
  ('spawideFractionSet', 'spa', 'wideFractionSet', 'Conjunto de fracciones para nombres amplios', 'Conjunto de fracciones para nombres amplios.', 'Para nombres amplios.', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('spawideMeasure', 'spa', 'wideMeasure', 'dentificación de medida (tabla ancha)', 'Identificador único para una medida solo en una tabla amplia. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawideName', 'spa', 'wideName', 'Nombre amplio', 'Identificador único solo para tablas amplias. Se utiliza cuando todas las medidas se realizan en una sola muestra al mismo tiempo y en el mismo laboratorio. Sugerencia: siteID_sampleID_LabID_reportDate_ID.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawideNames', 'spa', 'wideNames', 'Tabla de nombres amplios', 'La tabla para nombres amplios.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('spawideNamesOrder', 'spa', 'wideNamesOrder', 'Orden de tabla de nombres amplios', 'Columna para indicar el orden de los campos en la tabla de nombres amplios.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawideNamesRequired', 'spa', 'wideNamesRequired', 'Requisitos de tabla de nombres amplios', 'Columna para indicar qué campos de la tabla de nombres amplios son obligatorios.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawideNameType', 'spa', 'wideNameType', 'Tipo de nombre amplio', 'El tipo de nombre amplio generado. Las opciones posibles son medida, protocolo o atributo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawideProtocol', 'spa', 'wideProtocol', 'Protocolo especificado (tabla ancha)', 'Identificador único para un protocolo solo en una tabla amplia. ', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawideSpecimenSet', 'spa', 'wideSpecimenSet', 'Conjunto de especímenes para nombres amplios', 'Conjunto de especímenes para nombres amplios.', 'Para nombres amplios.', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('spawind', 'spa', 'wind', 'Velocidad del viento', 'Una medida de la velocidad del viento; parte de un conjunto más amplio de medidas meteorológicas que pueden ser útiles al recoger muestras de fuentes exteriores.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawindSpeedUnitSet', 'spa', 'windSpeedUnitSet', 'Conjunto de unidades de velocidad del viento', 'Conjunto de unidades para mediciones de la velocidad del viento.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawn', 'spa', 'wn', 'Nombre corto de tabla de nombres amplios', 'El nombre abreviado utilizado para hacer referencia a la tabla de nombres completos.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spawrongStorage', 'spa', 'wrongStorage', 'Muestra almacenada incorrectamente', 'La muestra se almacenó de forma inadecuada.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawrongTemp', 'spa', 'wrongTemp', 'Muestra almacenada a temperatura incorrecta', 'La muestra se almacenó a una temperatura inadecuada.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawSphere', 'spa', 'wSphere', 'Esfera Mundial (W‑SPHERE)', 'Encabezado World Sphere', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spawSphereForm', 'spa', 'wSphereForm', 'Formato W‑SPHERE', 'El conjunto de datos se registró y/o almacenó originalmente en formato wSphere.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spawSphereNotes', 'spa', 'wSphereNotes', 'Notas sobre W‑SPHERE (Esfera Mundial)', 'Notas de W-Shere', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawt214', 'spa', 'wt214', 'Diana génica wt214 (variante Delta)', 'Variante Delta wt214 gen objetivo', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawtfpl', 'spa', 'wtfpl', 'Licencia pública “Haz lo que te dé la p*ta gana”', 'La licencia de la medida o el conjunto de datos se gestiona bajo la licencia pública Do What The F*ck You Want To.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spawwtp', 'spa', 'wwtp', 'Planta de tratamiento de aguas residuales', 'Tipo de emplazamiento general para plantas de tratamiento de aguas residuales.', 'Se utiliza como categoría general para las plantas de tratamiento de aguas residuales industriales o municipales que transportan aguas residuales combinadas o sanitarias, o lagunas.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawwtpBack', 'spa', 'wwtpBack', 'Sitio de respaldo para tratamiento de aguas residuales', 'Indica una planta de tratamiento de aguas residuales en la que varios laboratorios están o han estado realizando muestreos, y en la que se están tomando muestras secundarias.', 'Se asigna a unidades de millones de galones por día o equivalentes de población.', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #123', NULL),
  ('spawwtpCap', 'spa', 'wwtpCap', 'Capacidad de diseño de la planta de tratamiento de aguas residuales', 'Medida de la capacidad diseñada de una planta de tratamiento de aguas residuales, en términos de la cantidad de agua que se diseñó para poder contener y procesar.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawwtpInd', 'spa', 'wwtpInd', 'Planta de tratamiento de aguas residuales industriales', 'Planta de tratamiento de aguas residuales industriales.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawwtpMuC', 'spa', 'wwtpMuC', 'Planta de tratamiento municipal para aguas residuales combinadas', 'Planta de tratamiento de aguas residuales municipales para aguas residuales combinadas.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spawwtpMuS', 'spa', 'wwtpMuS', 'Planta de tratamiento municipal para aguas sanitarias únicamente', 'Planta de tratamiento de aguas residuales municipales solo para aguas residuales sanitarias.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaxg', 'spa', 'xg', 'Fuerza centrífuga relativa (RCF) o unidades de x g', 'La RCF (fuerza centrífuga relativa) denota el grado de fuerza ejercida sobre una muestra. La RCF se cuantifica en múltiplos de la aceleración gravitatoria estándar en la superficie terrestre (x g). Por lo tanto, los términos RCF y XG se utilizan a menudo de forma intercambiable en los protocolos de centrifugación.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spay505h', 'spa', 'y505h', 'Diana génica y505h (variante ómicron)', 'y505h objetivo del gen de mutación de la variante Ómicron', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spayears', 'spa', 'years', 'Años', 'Unidad para indicar una duración en años.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spayEnterocolitica', 'spa', 'yEnterocolitica', 'Yersinia enterocolitica', 'Yersinia enterocolitica', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spayersiniaGrp', 'spa', 'yersiniaGrp', 'Grupo Yersinia', 'Grupo de medidas/métodos relacionados con la bacteria Yersinia.', 'Se utiliza para describir la información sobre organismos para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spazika', 'spa', 'zika', 'Zika', 'Zika', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spazlib', 'spa', 'zlib', 'Licencia zLib', 'La licencia de la medida o el conjunto de datos se gestiona bajo la licencia zLib.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spazo', 'spa', 'zo', 'Nombre corto de tabla de zonas', 'Nombre abreviado utilizado para hacer referencia a la tabla de consulta de las posibles entradas de regiones o zonas subnacionales.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spazoneName', 'spa', 'zoneName', 'Nombre en inglés de subdivisiones de país', 'Nombre en inglés de un subdominio de un país determinado.', 'Preprogramado en tablas de diccionario, no editable por los usuarios.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spazones', 'spa', 'zones', 'Tabla de búsqueda de zonas', 'Tabla de consulta de las posibles entradas de regiones o zonas subnacionales.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spazonesOrder', 'spa', 'zonesOrder', 'Orden de columnas en tabla de zonas', 'Especifica el orden de las columnas en la tabla de zonas.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spazonesRequired', 'spa', 'zonesRequired', 'Encabezados requeridos en tabla de zonas', 'Encabezados obligatorios en la tabla de zonas.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spazymo1035', 'spa', 'zymo1035', 'Kit Zymo Quick-RNA Viral #R1035', 'Kit zymo quick-rna viral #r1035.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spazymo1041', 'spa', 'zymo1041', 'Kit Zymo Quick-RNA Viral 96 #R1041', 'Kit zymo quick-rna viral 96 #r1041.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spazymoEnv', 'spa', 'zymoEnv', 'Kit Zymo Environ Water RNA / Zymo Environ Water RNA (cat. R2042)', 'Extracción de ácido nucleico realizada con el kit zymo environ water rna kit/ zymo environ water rna kit (cat. r2042).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spazymoQuick', 'spa', 'zymoQuick', 'Kit Zymo Quick-RNA Fungal/Bacterial Miniprep #R2014', 'Extracción de ácido nucleico realizada con el kit Zymo Quick-RNA Fungal/Bacterial Miniprep #R2014.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spazymoWatRNA', 'spa', 'zymoWatRNA', 'Kit Zymo Environ Water RNA / Zymo Environ Water RNA (cat. R2042)', 'Kit Zymo Environ Water RNA (cat. R2042)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaFALSE', 'spa', 'FALSE', 'FALSO', 'Tipo de datos booleanos = FALSO', 'Utilice estos valores y su conjunto para cualquier medida o atributo booleano. Utilice solo «FALSE» (distingue entre mayúsculas y minúsculas)', '1.0.0', '2.3.0', 'changed part ID from "false" to "FALSE".', NULL),
  ('spaTRUE', 'spa', 'TRUE', 'VERDADERO', 'Tipo de datos booleanos = VERDADERO', 'Utilice solo «TRUE» (distingue entre mayúsculas y minúsculas)', '1.0.0', '2.3.0', 'changed part ID from "true" to "TRUE".', NULL),
  ('engoverlap', 'eng', 'overlap', 'Overlapping relationship', 'Locations/polygon have overlapping portions.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engneighbour', 'eng', 'neighbour', 'Neighbouring relationship', 'Locations/polygon are neighbouring eachother.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fraoverlap', 'fra', 'overlap', 'Relation de chevauchement', 'Les emplacements/polygones présentent des portions qui se chevauchent.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('franeighbour', 'fra', 'neighbour', 'Relation de voisinage', 'Les emplacements/polygones sont voisins.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaoverlap', 'spa', 'overlap', 'Relación superpuesta', 'Las ubicaciones/polígonos tienen partes superpuestas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaneighbour', 'spa', 'neighbour', 'Relación vecinal', 'Las ubicaciones/polígonos son adyacentes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engcali', 'eng', 'cali', 'Calibration purpose', 'Purpose of calibrating a machine, method, or other.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('engdataType', 'eng', 'dataType', 'Data Type column (Reported)', 'The recorded data type for every part in the part table. This is the attribute in the parts table, not to be confused with dataTypes, the part type.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('engfKAliasID', 'eng', 'fKAliasID', 'Foreign Key Alias ID', 'The primary key that is being referenced by another name in another table as a foreign key.', 'For example, in the relationships tables, like sampleRelationships, "sampleIDObj" takes the value of a sampleID. It is sampleID as a foreign key, but under a different name. This column says what value is actually linked.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('enggeoRefMissingnessSet', 'eng', 'geoRefMissingnessSet', 'Geographical Reference Missingness Set', 'A missingness set for fields populated by the geographical reference tables (`countries`, `zones`).', 'Used for fields populated by geographical reference tables to avoid confusion of NA and nr as missingness indicators, vs. legitimate ISO country codes.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('engpartTypes', 'eng', 'partTypes', 'Part types part type', 'Part types describe the purpose or use of the part. Enivornment data has three main part types: measure (i.e. covN1 viral measures, wasteawater flow rate, temperature), method (e.g. how the measure was taken), and attribute (such as a site name). See description of each of the part types within setID = partTypeCatSets.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtag', 'eng', 'tag', 'Wide name measurement and linkage tag', 'A tag used in wide names to clarify relationship and linkage in the flattened, single table format.', 'If a column doesn''t have tag value at the end, then it means it applies to all groups, while one with a tag only applie to fields with the same tag value. For example, a value under qr_qualityFlag (with no tag) applies to fields in the group with tag == .odm10 and all other groups. If there''s a column called qr_qualityFlag.odm10, however, then the group with that .odm10 tag uses the value from qr_qualityFlag.odm10 instead of from qr_qualityFlag (like wat_sa_nr_hMe_hUn_hAg_NR_value.odm10 and mr_unit.odm10, for example).', '3.0.0', '3.0.1', 'missed in the V3.0.0 release, added with details in the V3.0.1 release.', NULL),
  ('fracali', 'fra', 'cali', 'Objectif de l''étalonnage', 'Objectif de l''étalonnage d''une machine, d''une méthode ou autre.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL);
INSERT INTO "translations" ("translationID", "lang", "partID", "label", "partDesc", "partInstr", "firstReleased", "lastUpdated", "changes", "notes") VALUES
  ('fradataType', 'fra', 'dataType', 'Colonne de type de données (déclarée)', 'Le type de données enregistré pour chaque partie dans la table des parties. Il s''agit de l''attribut dans la table des parties, à ne pas confondre avec dataTypes, le type de partie.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('frafKAliasID', 'fra', 'fKAliasID', 'Alias de ID de clé étrangère', 'La clé primaire qui est référencée sous un autre nom dans une autre table en tant que clé étrangère.', 'Par exemple, dans les tables de relations, comme sampleRelationships, « sampleIDObj » prend la valeur d''un sampleID. Il s''agit du sampleID en tant que clé étrangère, mais sous un nom différent. Cette colonne indique quelle valeur est réellement liée.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('frageoRefMissingnessSet', 'fra', 'geoRefMissingnessSet', 'Ensemble de valeurs manquantes pour les références géographiques', 'Un ensemble de valeurs manquantes pour les champs peuplés par les tables de référence géographique (countries, zones).', 'Utilisé pour les champs peuplés par les tables de référence géographique afin d''éviter la confusion entre NA et nr comme indicateurs de valeur manquante, et les codes de pays ISO légitimes.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('frapartTypes', 'fra', 'partTypes', 'Type(s) de partie(s)', 'Les types de parties décrivent l''objet ou l''usage de la partie. Les données environnementales comportent trois grands types de parties : mesure (par ex. les mesures virales de CoV-N1, le débit des eaux usées, la température), méthode (par ex. la façon dont la mesure a été prise) et attribut (comme le nom d''un site). Voir la description de chaque type de partie dans setID = partTypeCatSets.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fratag', 'fra', 'tag', 'Balise de liaison pour les noms larges et noms larges des mesures', 'Une balise utilisée dans les noms larges (wide names) pour clarifier la relation et le lien dans le format à table unique aplati.', 'Si une colonne n''a pas de valeur de balise à la fin, cela signifie qu''elle s''applique à tous les groupes, tandis qu''une colonne portant une balise ne s''applique qu''aux champs ayant la même valeur de balise. Par exemple, une valeur sous qr_qualityFlag (sans balise) s''applique aux champs du groupe portant la balise .odm10 ainsi qu''à tous les autres groupes. S''il existe cependant une colonne appelée qr_qualityFlag.odm10, alors le groupe portant cette balise .odm10 utilise la valeur de qr_qualityFlag.odm10 plutôt que celle de qr_qualityFlag (comme wat_sa_nr_hMe_hUn_hAg_NR_value.odm10 et mr_unit.odm10, par exemple).', '3.0.0', '3.0.1', 'missed in the V3.0.0 release, added with details in the V3.0.1 release.', NULL),
  ('spacali', 'spa', 'cali', 'Propósito de la calibración', 'Propósito de la calibración de una máquina, un método u otro.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('spadataType', 'spa', 'dataType', 'Tipo de datos de la columna (reportado)', 'El tipo de dato registrado para cada parte en la tabla de partes. Este es el atributo en la tabla de partes, que no debe confundirse con dataTypes, el tipo de parte.', 'NA', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('spafKAliasID', 'spa', 'fKAliasID', 'ID alias de clave externa', 'La clave primaria que está siendo referenciada bajo otro nombre en otra tabla como clave foránea.', 'Por ejemplo, en las tablas de relaciones, como sampleRelationships, «sampleIDObj» toma el valor de un sampleID. Es el sampleID como clave foránea, pero bajo un nombre diferente. Esta columna indica qué valor está realmente vinculado.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('spageoRefMissingnessSet', 'spa', 'geoRefMissingnessSet', 'Conjunto de valores faltantes de referencia geográfica', 'Un conjunto de valores faltantes para campos poblados por las tablas de referencia geográfica (countries, zones).', 'Se utiliza para campos poblados por las tablas de referencia geográfica para evitar la confusión entre NA y nr como indicadores de valor faltante, frente a códigos de país ISO legítimos.', '3.0.1', '3.0.1', 'added in V3.0.1', NULL),
  ('spapartTypes', 'spa', 'partTypes', 'Tipo(s) de parte(s)', 'Los tipos de partes describen el propósito o el uso de la parte. Los datos ambientales tienen tres tipos de partes principales: medida (p. ej., las medidas virales de CoV-N1, el caudal de aguas residuales, la temperatura), método (p. ej., cómo se tomó la medida) y atributo (como el nombre de un sitio). Consulte la descripción de cada tipo de parte en setID = partTypeCatSets.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spatag', 'spa', 'tag', 'Etiqueta de vinculación para las medidas y nombres anchos', 'Una etiqueta utilizada en los nombres anchos (wide names) para aclarar la relación y el enlace en el formato de tabla única aplanada.', 'Si una columna no tiene un valor de etiqueta al final, significa que se aplica a todos los grupos, mientras que una con etiqueta solo se aplica a los campos con el mismo valor de etiqueta. Por ejemplo, un valor bajo qr_qualityFlag (sin etiqueta) se aplica a los campos del grupo con la etiqueta .odm10 y a todos los demás grupos. Sin embargo, si existe una columna llamada qr_qualityFlag.odm10, el grupo con esa etiqueta .odm10 usa el valor de qr_qualityFlag.odm10 en lugar de qr_qualityFlag (como wat_sa_nr_hMe_hUn_hAg_NR_value.odm10 y mr_unit.odm10, por ejemplo).', '3.0.0', '3.0.1', 'missed in the V3.0.0 release, added with details in the V3.0.1 release.', NULL),
  ('engac', 'eng', 'ac', 'Accessions report table Shorthand', 'The abbreviated short name used to reference the report table for accessions and accessionIDs.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('fraac', 'fra', 'ac', 'Raccourci du tableau des accessions', 'Nom abrégé utilisé pour faire référence au tableau de rapport pour les accessions et les accessionID.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaac', 'spa', 'ac', 'Abreviatura de tabla de informes de accesiones', 'Nombre abreviado utilizado para referenciar la tabla de reporte para accesiones e IDs de accesión.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engarticV1', 'eng', 'articV1', 'Artic V1 Primer Set', 'An amplicon strategy which was developed by the ARTIC consortium for SARS-CoV-2 with the attributes of version 1.0.0.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
